_SOURCES['blocks.bar_chart_block'] = '"""\nBloc "Graphique en bâtonnets" (PATCH 47, révisé PATCH 49, PATCH 54, PATCH 59).\n\nBarres "Prévu" (bleu) avec, pour chacune, une valeur "Réel"\noptionnelle affichée sous forme de marqueur en pointillés (rouge si\nle réel dépasse le prévu — dépassement de budget —, vert sinon).\nUtilisé par exemple pour le graphique "Delta de budget" du template.\n\nPATCH 54 : le graphique peut désormais être relié à un bloc "Planning\npar dépendances" (`source_gantt_id`), et regroupé par une colonne\ntexte de son tableau source (`group_column_id`, ex : "Phases"). Une\nfois relié, les barres ne sont plus éditées manuellement : elles sont\nrecalculées en direct à chaque lecture.\n\nPATCH 59 : l\'édition manuelle des barres a été retirée (la ligne\n"Phase / Prévu / Réel" + bouton "Ajouter une barre" ne servait plus à\nrien une fois le graphique toujours relié à une source). Le calcul se\nbase désormais, par défaut, sur deux colonnes "Nombre" du tableau\nsource (`value_column_id`/`actual_column_id`, ex : "Prix estimé" /\n"Prix réel") plutôt que sur la durée/l\'écart en jours des\nsous-tâches — utilisé notamment pour "Delta de budget", qui n\'a\njamais représenté un nombre de jours mais bien un montant. Si aucune\ncolonne de prix n\'est choisie, on retombe sur l\'ancien calcul\ndurée + écart (voir sync_bars_from_gantt).\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any, Optional\n\nfrom core.block import Block\n\nBAR_CHART_BLOCK_TYPE = "bar_chart"\n\nPLANNED_BAR_COLOR = "#1976d2"\nOVER_BUDGET_COLOR = "#e53935"\nUNDER_BUDGET_COLOR = "#43a047"\n\n\nclass BarChartBlock(Block):\n    """Bloc graphique en bâtonnets, toujours recalculé à partir d\'un\n    planning par dépendances relié (PATCH 59 — plus d\'édition manuelle).\n\n    Données (data) :\n        title: titre affiché au-dessus du graphique.\n        y_axis_label: libellé de l\'axe des ordonnées (ex : "Prix").\n        source_gantt_id: id d\'un DependencyGanttBlock. Si None, aucune\n            barre n\'est affichée (voir sync_bars_from_gantt).\n        group_column_id: id d\'une colonne texte du tableau source du\n            Gantt relié, utilisée pour regrouper les sous-tâches en\n            barres (ex : "Phases"). Si None, chaque sous-tâche forme\n            sa propre barre.\n        value_column_id / actual_column_id (PATCH 59) : id de colonnes\n            "Nombre" du tableau source utilisées comme montant "Prévu"\n            / "Réel" (ex : "Prix estimé" / "Prix réel"). Si\n            value_column_id est None, repli sur l\'ancien calcul\n            durée + écart ("Ecarts") des sous-tâches.\n    """\n\n    def __init__(\n        self,\n        title: str = "Graphique",\n        y_axis_label: str = "",\n        source_gantt_id: Optional[str] = None,\n        group_column_id: Optional[str] = None,\n        value_column_id: Optional[str] = None,\n        actual_column_id: Optional[str] = None,\n        id: str | None = None,\n    ) -> None:\n        super().__init__(\n            type=BAR_CHART_BLOCK_TYPE,\n            data={\n                "title": title,\n                "y_axis_label": y_axis_label,\n                "source_gantt_id": source_gantt_id,\n                "group_column_id": group_column_id,\n                "value_column_id": value_column_id,\n                "actual_column_id": actual_column_id,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def title(self) -> str:\n        return self.data.get("title", "")\n\n    @title.setter\n    def title(self, value: str) -> None:\n        self.data["title"] = value\n\n    @property\n    def y_axis_label(self) -> str:\n        return self.data.get("y_axis_label", "")\n\n    @y_axis_label.setter\n    def y_axis_label(self, value: str) -> None:\n        self.data["y_axis_label"] = value\n\n    @property\n    def source_gantt_id(self) -> Optional[str]:\n        return self.data.get("source_gantt_id")\n\n    @property\n    def group_column_id(self) -> Optional[str]:\n        return self.data.get("group_column_id")\n\n    @property\n    def value_column_id(self) -> Optional[str]:\n        return self.data.get("value_column_id")\n\n    @property\n    def actual_column_id(self) -> Optional[str]:\n        return self.data.get("actual_column_id")\n\n    def set_source(\n        self,\n        source_gantt_id: Optional[str],\n        group_column_id: Optional[str] = None,\n        value_column_id: Optional[str] = None,\n        actual_column_id: Optional[str] = None,\n    ) -> None:\n        """PATCH 54, étendu PATCH 59 — Relie (ou détache si None) ce\n        graphique à un DependencyGanttBlock ; `group_column_id` choisit\n        le regroupement des sous-tâches en barres ; `value_column_id`/\n        `actual_column_id` choisissent les colonnes "Prévu"/"Réel"\n        (repli sur durée + écart si `value_column_id` est None)."""\n        self.data["source_gantt_id"] = source_gantt_id\n        self.data["group_column_id"] = group_column_id\n        self.data["value_column_id"] = value_column_id\n        self.data["actual_column_id"] = actual_column_id\n\n\ndef budget_marker_color(bar: dict[str, Any]) -> Optional[str]:\n    """Couleur du marqueur "Réel" : rouge en dépassement de budget\n    (réel > prévu), vert sinon. None si aucun "Réel" renseigné."""\n    if bar.get("actual") is None:\n        return None\n    return OVER_BUDGET_COLOR if bar["actual"] > bar["value"] else UNDER_BUDGET_COLOR\n\n\ndef _to_number(value: Any) -> float:\n    try:\n        return float(str(value).replace(",", ".").strip() or 0)\n    except (TypeError, ValueError):\n        return 0.0\n\n\ndef sync_bars_from_gantt(document, block: "BarChartBlock") -> list[dict[str, Any]]:\n    """PATCH 54, étendu PATCH 59 — Recalcule les barres en direct à\n    partir d\'un planning par dépendances relié (`block.source_gantt_id`),\n    jamais stockées (même principe que compute_schedule/\n    compute_efficiency_ratio).\n\n    Si `value_column_id` est configuré (ex : "Prix estimé"), "Prévu"/\n    "Réel" viennent de ces deux colonnes "Nombre" du tableau source\n    (PATCH 59). Sinon, repli sur l\'ancien calcul : "Prévu" = durée,\n    "Réel" = durée + écart ("Ecarts"). Les sous-tâches sont regroupées\n    par `group_column_id` (une colonne texte du tableau source, ex :\n    "Phases") si définie, sinon chacune forme sa propre barre. Liste\n    vide si non relié ou planning vide.\n    """\n    # Import différé : évite un import circulaire (dependency_gantt_block\n    # ne dépend pas de bar_chart_block, mais les deux modules de blocs\n    # sont souvent importés ensemble au niveau du registre).\n    from blocks.dependency_gantt_block import DependencyGanttBlock, compute_schedule, find_source_table\n\n    if block.source_gantt_id is None:\n        return []\n    gantt = document.find_block(block.source_gantt_id)\n    if not isinstance(gantt, DependencyGanttBlock):\n        return []\n    schedule = compute_schedule(document, gantt)\n    if not schedule:\n        return []\n\n    table = find_source_table(document, gantt)\n    group_column = None\n    if table is not None and block.group_column_id:\n        group_column = table._find_column(block.group_column_id)\n    rows_by_id = {row["id"]: row for row in table.rows} if table is not None else {}\n\n    value_column = None\n    actual_column = None\n    if table is not None and block.value_column_id:\n        value_column = table._find_column(block.value_column_id)\n    if table is not None and block.actual_column_id:\n        actual_column = table._find_column(block.actual_column_id)\n    use_price_columns = value_column is not None\n\n    order: list[str] = []\n    totals: dict[str, dict[str, Any]] = {}\n    for task in schedule:\n        row = rows_by_id.get(task["row_id"])\n        if group_column is not None:\n            key = str(row["cells"].get(group_column["id"], "")) if row is not None else task["label"]\n        else:\n            key = task["label"]\n        if key not in totals:\n            totals[key] = {\n                "value": 0.0,\n                # PATCH 59 — sans colonne "Réel" configurée, aucun\n                # marqueur n\'est affiché (None), plutôt qu\'un 0 trompeur.\n                "actual": 0.0 if (not use_price_columns or actual_column is not None) else None,\n            }\n            order.append(key)\n\n        if use_price_columns:\n            totals[key]["value"] += _to_number(row["cells"].get(value_column["id"])) if row is not None else 0.0\n            if actual_column is not None:\n                totals[key]["actual"] += _to_number(row["cells"].get(actual_column["id"])) if row is not None else 0.0\n        else:\n            totals[key]["value"] += task["duration"]\n            totals[key]["actual"] += task["duration"] + task["delta"]\n\n    return [\n        {\n            "id": key,\n            "label": key,\n            "value": totals[key]["value"],\n            "actual": totals[key]["actual"],\n            "color": PLANNED_BAR_COLOR,\n        }\n        for key in order\n    ]'
_SOURCES['blocks.checklist_block'] = '"""\nBloc Checklist.\n\nChaque élément de la checklist possède un texte et un état\ncoché/décoché. L\'ordre des éléments dans la liste est significatif.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any\n\nfrom core.block import Block\n\nCHECKLIST_BLOCK_TYPE = "checklist"\n\n\nclass ChecklistBlock(Block):\n    """Bloc de liste à cocher.\n\n    Les données du bloc contiennent une seule clé "items" : une\n    liste de dictionnaires {"text": str, "checked": bool}.\n    """\n\n    def __init__(\n        self,\n        items: list[dict[str, Any]] | None = None,\n        id: str | None = None,\n    ) -> None:\n        # Rétrocompatibilité : les checklists sauvegardées avant ce\n        # correctif n\'ont pas d\'"id" par élément ; on leur en génère un.\n        normalized_items: list[dict[str, Any]] = []\n        for item in items or []:\n            normalized_items.append({**item, "id": item.get("id") or str(uuid.uuid4())})\n\n        super().__init__(\n            type=CHECKLIST_BLOCK_TYPE,\n            data={"items": normalized_items},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def items(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("items", [])\n\n    def _find_item(self, item_id: str) -> dict[str, Any] | None:\n        for item in self.items:\n            if item.get("id") == item_id:\n                return item\n        return None\n\n    def add_item(self, text: str = "", checked: bool = False) -> dict[str, Any]:\n        """Ajoute un élément et le retourne (avec son id généré)."""\n        item = {"id": str(uuid.uuid4()), "text": text, "checked": checked}\n        self.items.append(item)\n        return item\n\n    def remove_item(self, item_id: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        self.items.remove(item)\n        return True\n\n    def set_item_text(self, item_id: str, text: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        item["text"] = text\n        return True\n\n    def set_item_checked(self, item_id: str, checked: bool) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        item["checked"] = checked\n        return True\n\n    def sort_by_status(self) -> None:\n        """Trie la liste : tâches non cochées d\'abord, cochées ensuite (PATCH 11).\n\n        Tri stable : l\'ordre relatif à l\'intérieur de chaque groupe\n        (non coché / coché) est conservé.\n        """\n        self.data["items"] = sorted(\n            self.items, key=lambda item: bool(item.get("checked", False))\n        )\n'
_SOURCES['blocks.code_block'] = '"""\nBloc Code (PATCH 22).\n\nBloc de texte brut destiné au code : police monospace à l\'affichage.\nLa coloration syntaxique est explicitement une amélioration future\n(voir le plan du projet) — ce patch pose la structure de données et\nl\'affichage monospace uniquement.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nCODE_BLOCK_TYPE = "code"\n\n# Langage par défaut, informatif seulement (pas encore utilisé pour\n# la coloration syntaxique, prévue dans une amélioration future).\nDEFAULT_LANGUAGE = "text"\n\n\nclass CodeBlock(Block):\n    """Bloc de code : texte brut affiché en police monospace.\n\n    Attributes (dans data):\n        content: code brut, sans mise en forme.\n        language: étiquette de langage (informative pour l\'instant).\n    """\n\n    def __init__(self, content: str = "", language: str = DEFAULT_LANGUAGE, id: str | None = None) -> None:\n        super().__init__(\n            type=CODE_BLOCK_TYPE,\n            data={"content": content, "language": language},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def content(self) -> str:\n        return self.data.get("content", "")\n\n    @content.setter\n    def content(self, value: str) -> None:\n        self.data["content"] = value\n\n    @property\n    def language(self) -> str:\n        return self.data.get("language", DEFAULT_LANGUAGE)\n\n    @language.setter\n    def language(self, value: str) -> None:\n        self.data["language"] = value or DEFAULT_LANGUAGE\n'
_SOURCES['blocks.dependency_gantt_block'] = '"""\nBloc "Gantt (dépendances)" (PATCH 46, révisé PATCH 49).\n\nContrairement à GanttBlock (qui lit des dates absolues), ce bloc\ncalcule un planning à partir de DURÉES (colonne "Nombre", en jours)\net de DÉPENDANCES entre sous-tâches (colonne "Liste multiple", dont\nles valeurs sont les libellés d\'autres lignes) : la date de début\nd\'une sous-tâche est déterminée par la résolution de ses dépendances,\npas par une date saisie.\n\nDeux façons de déclarer un retard/avance (en jours) sur une\nsous-tâche :\n    - `delta_column_id` (PATCH 49) : référence vers une colonne\n      "Nombre" du tableau source (ex : "Ecarts"). Dès qu\'elle est\n      configurée, c\'est TOUJOURS elle qui fait foi — l\'écart se\n      règle alors directement dans le tableau, comme n\'importe\n      quelle autre valeur d\'une sous-tâche.\n    - `deltas` (historique, PATCH 46) : dictionnaire {row_id: jours}\n      propre au bloc, utilisé uniquement tant qu\'aucune\n      `delta_column_id` n\'est configurée (rétrocompatibilité avec\n      les documents créés avant PATCH 49).\n\nLe point de résolution d\'une sous-tâche (utilisé comme date de début\ndes sous-tâches qui en dépendent) est toujours `fin_planifiée + delta` :\n    - delta > 0 : la sous-tâche a fini en retard, la barre est\n      prolongée en noir jusqu\'à ce point.\n    - delta < 0 : la sous-tâche a fini en avance, le temps gagné (la\n      fin de la barre normale) est recoloré en bleu.\n    - delta == 0 : résolution à l\'heure, à la fin planifiée.\n\nLe planning est toujours calculé et stocké EN JOURS ; PATCH 49\najoute uniquement un affichage optionnel "en mois" côté widget\n(`DAYS_PER_MONTH` / `format_duration_in_unit` ci-dessous), sans\njamais changer l\'unité de stockage.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any, Optional\n\nfrom blocks.table_block import (\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_PERSON,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_TEXT,\n    TableBlock,\n)\nfrom core.block import Block\n\nDEPENDENCY_GANTT_BLOCK_TYPE = "dependency_gantt"\n\nRISK_COLORS: dict[str, str] = {\n    "vert": "#4caf50",\n    "orange": "#ff9800",\n    "rouge": "#f44336",\n}\n_DEFAULT_BAR_COLOR = "#4db6ac"\n\n# PATCH 49 — équivalence utilisée uniquement pour l\'affichage "en mois"\n# (le stockage reste toujours en jours).\nDAYS_PER_MONTH = 30.0\n\nUNIT_DAYS = "jours"\nUNIT_MONTHS = "mois"\n\n\ndef format_duration_in_unit(days: float, unit: str) -> str:\n    """Formate une durée (toujours reçue en jours) pour l\'affichage,\n    selon `unit` ("jours" ou "mois"). Ne change jamais la valeur\n    stockée, uniquement le texte affiché."""\n    if unit == UNIT_MONTHS:\n        return f"{days / DAYS_PER_MONTH:g} mois"\n    return f"{days:g} j"\n\n\nclass DependencyGanttBlock(Block):\n    """Bloc Gantt calculé à partir de durées et de dépendances.\n\n    Données (data) :\n        table_block_id / label_column_id / person_column_id /\n        duration_column_id / risk_column_id / dependency_column_id :\n            références vers le TableBlock source (mêmes principes que\n            GanttBlock : rien d\'autre n\'est dupliqué ici).\n        deltas: {row_id: float} — retard (positif) ou avance\n            (négatif) déclaré manuellement sur une sous-tâche.\n    """\n\n    def __init__(\n        self,\n        table_block_id: Optional[str] = None,\n        label_column_id: Optional[str] = None,\n        person_column_id: Optional[str] = None,\n        duration_column_id: Optional[str] = None,\n        risk_column_id: Optional[str] = None,\n        dependency_column_id: Optional[str] = None,\n        delta_column_id: Optional[str] = None,\n        deltas: dict[str, float] | None = None,\n        time_unit: str = UNIT_DAYS,\n        phase_column_id: Optional[str] = None,\n        id: str | None = None,\n    ) -> None:\n        super().__init__(\n            type=DEPENDENCY_GANTT_BLOCK_TYPE,\n            data={\n                "table_block_id": table_block_id,\n                "label_column_id": label_column_id,\n                "person_column_id": person_column_id,\n                "duration_column_id": duration_column_id,\n                "risk_column_id": risk_column_id,\n                "dependency_column_id": dependency_column_id,\n                "delta_column_id": delta_column_id,\n                "deltas": dict(deltas or {}),\n                "time_unit": time_unit,\n                # PATCH 74 — colonne texte optionnelle (ex : "Phases") pour\n                # regrouper les sous-tâches et afficher des séparateurs\n                # verticaux étiquetés sur le graphique (voir compute_schedule\n                # et _DependencyGanttCanvas._update_phase_groups).\n                "phase_column_id": phase_column_id,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def table_block_id(self) -> Optional[str]:\n        return self.data.get("table_block_id")\n\n    @property\n    def label_column_id(self) -> Optional[str]:\n        return self.data.get("label_column_id")\n\n    @property\n    def person_column_id(self) -> Optional[str]:\n        return self.data.get("person_column_id")\n\n    @property\n    def duration_column_id(self) -> Optional[str]:\n        return self.data.get("duration_column_id")\n\n    @property\n    def risk_column_id(self) -> Optional[str]:\n        return self.data.get("risk_column_id")\n\n    @property\n    def dependency_column_id(self) -> Optional[str]:\n        return self.data.get("dependency_column_id")\n\n    @property\n    def delta_column_id(self) -> Optional[str]:\n        return self.data.get("delta_column_id")\n\n    @property\n    def phase_column_id(self) -> Optional[str]:\n        return self.data.get("phase_column_id")\n\n    @property\n    def time_unit(self) -> str:\n        """PATCH 49 — unité d\'affichage de l\'axe temporel et des valeurs\n        chiffrées du planning ("jours" ou "mois"). Le stockage interne\n        reste toujours en jours, voir format_duration_in_unit()."""\n        return self.data.get("time_unit", UNIT_DAYS)\n\n    @time_unit.setter\n    def time_unit(self, value: str) -> None:\n        self.data["time_unit"] = value if value in (UNIT_DAYS, UNIT_MONTHS) else UNIT_DAYS\n\n    def set_source(\n        self,\n        table_block_id: Optional[str],\n        label_column_id: Optional[str] = None,\n        person_column_id: Optional[str] = None,\n        duration_column_id: Optional[str] = None,\n        risk_column_id: Optional[str] = None,\n        dependency_column_id: Optional[str] = None,\n        delta_column_id: Optional[str] = None,\n        phase_column_id: Optional[str] = None,\n    ) -> None:\n        self.data["table_block_id"] = table_block_id\n        self.data["label_column_id"] = label_column_id\n        self.data["person_column_id"] = person_column_id\n        self.data["duration_column_id"] = duration_column_id\n        self.data["risk_column_id"] = risk_column_id\n        self.data["dependency_column_id"] = dependency_column_id\n        self.data["delta_column_id"] = delta_column_id\n        self.data["phase_column_id"] = phase_column_id\n\n    @property\n    def deltas(self) -> dict[str, float]:\n        return self.data.setdefault("deltas", {})\n\n    def get_delta(self, row_id: str) -> float:\n        return float(self.deltas.get(row_id, 0.0))\n\n    def set_delta(self, row_id: str, value: float) -> None:\n        if value:\n            self.deltas[row_id] = float(value)\n        else:\n            self.deltas.pop(row_id, None)\n\n\ndef find_source_table(document, block: DependencyGanttBlock) -> Optional[TableBlock]:\n    if block.table_block_id is None:\n        return None\n    found = document.find_block(block.table_block_id)\n    return found if isinstance(found, TableBlock) else None\n\n\ndef available_label_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_TEXT]\n\n\ndef available_person_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_PERSON]\n\n\ndef available_duration_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_NUMBER]\n\n\ndef available_delta_columns(table: TableBlock) -> list[dict[str, Any]]:\n    """Colonnes "Nombre" utilisables comme colonne d\'écart ("Ecarts") —\n    même filtre que la durée : n\'importe quelle colonne numérique."""\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_NUMBER]\n\n\ndef available_risk_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_SELECT]\n\n\ndef available_dependency_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_MULTI_SELECT]\n\n\ndef available_phase_columns(table: TableBlock) -> list[dict[str, Any]]:\n    """PATCH 74 — Colonnes texte utilisables pour regrouper les\n    sous-tâches par phase (mêmes candidates que les libellés)."""\n    return [c for c in table.columns if c["type"] == COLUMN_TYPE_TEXT]\n\n\ndef _to_number(value: Any) -> float:\n    try:\n        return float(str(value).replace(",", ".").strip() or 0)\n    except (TypeError, ValueError):\n        return 0.0\n\n\ndef compute_efficiency_ratio(document, block: "DependencyGanttBlock") -> Optional[float]:\n    """Ratio "vélocité réelle" = durée planifiée totale / (durée planifiée\n    totale + retard total), utilisé par le bloc graphique "Courbes"\n    pour tracer une droite de vélocité réelle du planning. None si le\n    planning est vide ou sans aucune durée."""\n    schedule = compute_schedule(document, block)\n    if not schedule:\n        return None\n    total_duration = sum(t["duration"] for t in schedule)\n    total_delay = sum(max(t["delta"], 0.0) for t in schedule)\n    denominator = total_duration + total_delay\n    if denominator <= 0:\n        return None\n    return total_duration / denominator\n\n\ndef compute_schedule(document, block: DependencyGanttBlock) -> list[dict[str, Any]]:\n    """Calcule le planning complet à partir de l\'état actuel du document.\n\n    Retourne une liste (dans l\'ordre des lignes du tableau) de :\n        {row_id, label, person_names, risk, dependencies (libellés),\n         duration, planned_start, planned_end, start, end, resolution,\n         delta}\n    "start"/"end" sont les bornes de la barre normale (après décalage\n    en cascade par les dépendances) ; "resolution" est le point où la\n    sous-tâche est effectivement considérée comme terminée, utilisé\n    comme point de départ des sous-tâches qui en dépendent.\n    """\n    table = find_source_table(document, block)\n    if table is None:\n        return []\n\n    label_column = table._find_column(block.label_column_id) if block.label_column_id else None\n    duration_column = table._find_column(block.duration_column_id) if block.duration_column_id else None\n    person_column = table._find_column(block.person_column_id) if block.person_column_id else None\n    risk_column = table._find_column(block.risk_column_id) if block.risk_column_id else None\n    dependency_column = table._find_column(block.dependency_column_id) if block.dependency_column_id else None\n    delta_column = table._find_column(block.delta_column_id) if block.delta_column_id else None\n    phase_column = table._find_column(block.phase_column_id) if block.phase_column_id else None\n\n    if label_column is None or duration_column is None:\n        return []\n\n    # Résolution des dépendances par libellé (premier match si doublon).\n    row_id_by_label: dict[str, str] = {}\n    for row in table.rows:\n        label = str(row["cells"].get(label_column["id"], ""))\n        row_id_by_label.setdefault(label, row["id"])\n\n    rows_by_id = {row["id"]: row for row in table.rows}\n\n    def _dependency_row_ids(row: dict[str, Any]) -> list[str]:\n        if dependency_column is None:\n            return []\n        labels = row["cells"].get(dependency_column["id"]) or []\n        return [row_id_by_label[label] for label in labels if label in row_id_by_label]\n\n    def _duration(row: dict[str, Any]) -> float:\n        return max(_to_number(row["cells"].get(duration_column["id"])), 0.0)\n\n    def _get_delta(row: dict[str, Any], row_id: str) -> float:\n        """L\'écart vient de la colonne "Ecarts" si configurée (PATCH 49),\n        sinon repli sur l\'ancien stockage `deltas` du bloc (documents\n        enregistrés avant cette colonne)."""\n        if delta_column is not None:\n            return _to_number(row["cells"].get(delta_column["id"]))\n        return block.get_delta(row_id)\n\n    memo: dict[str, dict[str, float]] = {}\n\n    def _resolve(row_id: str, visiting: set[str]) -> dict[str, float]:\n        if row_id in memo:\n            return memo[row_id]\n        row = rows_by_id.get(row_id)\n        if row is None:\n            result = {"start": 0.0, "end": 0.0, "resolution": 0.0}\n            memo[row_id] = result\n            return result\n        if row_id in visiting:\n            # Dépendance circulaire : on casse la boucle en ignorant les\n            # dépendances de cette ligne plutôt que de boucler à l\'infini.\n            start = 0.0\n        else:\n            visiting = visiting | {row_id}\n            dep_ids = _dependency_row_ids(row)\n            start = max((_resolve(dep_id, visiting)["resolution"] for dep_id in dep_ids), default=0.0)\n\n        duration = _duration(row)\n        end = start + duration\n        delta = _get_delta(row, row_id)\n        resolution = end + delta\n        result = {"start": start, "end": end, "resolution": resolution}\n        memo[row_id] = result\n        return result\n\n    people_by_id = {person["id"]: person for person in document.people}\n\n    schedule: list[dict[str, Any]] = []\n    for row in table.rows:\n        computed = _resolve(row["id"], set())\n        person_ids = row["cells"].get(person_column["id"], []) if person_column else []\n        person_names = [people_by_id[pid]["name"] for pid in person_ids if pid in people_by_id]\n        risk = row["cells"].get(risk_column["id"], "") if risk_column else ""\n        dependencies = row["cells"].get(dependency_column["id"], []) if dependency_column else []\n        schedule.append(\n            {\n                "row_id": row["id"],\n                "label": str(row["cells"].get(label_column["id"], "")),\n                "person_names": person_names,\n                "risk": risk,\n                "color": RISK_COLORS.get(risk, _DEFAULT_BAR_COLOR),\n                "dependencies": list(dependencies),\n                "duration": _duration(row),\n                "start": computed["start"],\n                "end": computed["end"],\n                "resolution": computed["resolution"],\n                "delta": _get_delta(row, row["id"]),\n                # PATCH 74 — vide si aucune colonne "Phases" configurée.\n                "phase": str(row["cells"].get(phase_column["id"], "")) if phase_column else "",\n            }\n        )\n    return schedule'
_SOURCES['blocks.formula_block'] = '"""\nBloc "Résultat calculé" (PATCH 45).\n\nComme GanttBlock, ne stocke AUCUNE donnée de projet : uniquement une\nréférence (id du TableBlock visé, id d\'une colonne "Nombre" et d\'une\ncolonne "Booléen" de ce tableau) et un libellé. Le résultat affiché\n(somme de la colonne "Nombre" pour les lignes où la colonne\n"Booléen" est cochée, sur somme totale de la colonne "Nombre") est\nentièrement recalculé à chaque lecture, à partir de l\'état courant\ndu Document.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any, Optional\n\nfrom blocks.table_block import COLUMN_TYPE_BOOLEAN, COLUMN_TYPE_NUMBER, TableBlock\nfrom core.block import Block\n\nFORMULA_BLOCK_TYPE = "formula"\n\n_DEFAULT_LABEL = "Résultat: "\n\n\nclass FormulaBlock(Block):\n    """Bloc de résultat calculé : référence vers un TableBlock + 2 colonnes.\n\n    Données (data) :\n        table_block_id: id du TableBlock source (ou None si non configuré).\n        number_column_id: id de la colonne "Nombre" à sommer.\n        boolean_column_id: id de la colonne "Booléen" utilisée comme filtre.\n        label: texte affiché avant le résultat (ex: "Résultat: ").\n    """\n\n    def __init__(\n        self,\n        table_block_id: Optional[str] = None,\n        number_column_id: Optional[str] = None,\n        boolean_column_id: Optional[str] = None,\n        label: str = _DEFAULT_LABEL,\n        id: str | None = None,\n    ) -> None:\n        super().__init__(\n            type=FORMULA_BLOCK_TYPE,\n            data={\n                "table_block_id": table_block_id,\n                "number_column_id": number_column_id,\n                "boolean_column_id": boolean_column_id,\n                "label": label,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def table_block_id(self) -> Optional[str]:\n        return self.data.get("table_block_id")\n\n    @property\n    def number_column_id(self) -> Optional[str]:\n        return self.data.get("number_column_id")\n\n    @property\n    def boolean_column_id(self) -> Optional[str]:\n        return self.data.get("boolean_column_id")\n\n    @property\n    def label(self) -> str:\n        return self.data.get("label", _DEFAULT_LABEL)\n\n    @label.setter\n    def label(self, value: str) -> None:\n        self.data["label"] = value\n\n    def set_source(\n        self,\n        table_block_id: Optional[str],\n        number_column_id: Optional[str] = None,\n        boolean_column_id: Optional[str] = None,\n    ) -> None:\n        """Configure (ou reconfigure) la source du calcul."""\n        self.data["table_block_id"] = table_block_id\n        self.data["number_column_id"] = number_column_id\n        self.data["boolean_column_id"] = boolean_column_id\n\n\ndef find_source_table(document, formula_block: FormulaBlock) -> Optional[TableBlock]:\n    """Retrouve le TableBlock référencé par le calcul dans le document courant."""\n    if formula_block.table_block_id is None:\n        return None\n    block = document.find_block(formula_block.table_block_id)\n    return block if isinstance(block, TableBlock) else None\n\n\ndef available_number_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [column for column in table.columns if column["type"] == COLUMN_TYPE_NUMBER]\n\n\ndef available_boolean_columns(table: TableBlock) -> list[dict[str, Any]]:\n    return [column for column in table.columns if column["type"] == COLUMN_TYPE_BOOLEAN]\n\n\ndef _to_number(value: Any) -> float:\n    try:\n        return float(str(value).replace(",", ".").strip() or 0)\n    except (TypeError, ValueError):\n        return 0.0\n\n\ndef compute_formula_result(document, formula_block: FormulaBlock) -> Optional[tuple[float, float]]:\n    """Recalcule (somme_cochée, somme_totale) à partir de l\'état actuel du\n    document, ou None si la source n\'est pas (ou plus) valide.\n\n    Ne lit ni ne modifie aucune donnée propre au FormulaBlock : tout\n    vient du TableBlock référencé, relu à chaque appel (même principe\n    que compute_gantt_rows pour le bloc Gantt).\n    """\n    table = find_source_table(document, formula_block)\n    if table is None:\n        return None\n\n    number_column = table._find_column(formula_block.number_column_id) if formula_block.number_column_id else None\n    if number_column is None or number_column["type"] != COLUMN_TYPE_NUMBER:\n        return None\n\n    boolean_column = table._find_column(formula_block.boolean_column_id) if formula_block.boolean_column_id else None\n    if boolean_column is None or boolean_column["type"] != COLUMN_TYPE_BOOLEAN:\n        return None\n\n    total = 0.0\n    checked_total = 0.0\n    for row in table.rows:\n        value = _to_number(row["cells"].get(number_column["id"]))\n        total += value\n        if row["cells"].get(boolean_column["id"]):\n            checked_total += value\n    return checked_total, total\n\n\ndef _format_number(value: float) -> str:\n    """Affiche les entiers sans décimale (ex: 12 plutôt que 12.0)."""\n    if value == int(value):\n        return str(int(value))\n    return str(value)\n\n\ndef format_formula_text(formula_block: FormulaBlock, result: Optional[tuple[float, float]]) -> str:\n    if result is None:\n        return f"{formula_block.label}(source non configurée)"\n    checked_total, total = result\n    return f"{formula_block.label}{_format_number(checked_total)} / {_format_number(total)}"\n'
_SOURCES['blocks.gantt_block'] = '"""\nBloc Gantt (PATCH 19).\n\nLe bloc Gantt ne stocke AUCUNE donnée de projet : il conserve\nuniquement une référence (id du bloc Tableau visé, id de la colonne\nutilisée comme libellé, id de la colonne Date utilisée pour les\nbarres). Toute lecture recalcule les barres à partir de l\'état actuel\ndu Document ; une modification du tableau est donc reflétée sans\naucune synchronisation manuelle, puisqu\'il n\'y a rien à synchroniser.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any, Optional\n\nfrom blocks.table_block import COLUMN_TYPE_DATE, COLUMN_TYPE_TEXT, TableBlock\nfrom core.block import Block\n\nGANTT_BLOCK_TYPE = "gantt"\n\n\nclass GanttBlock(Block):\n    """Bloc Gantt : simple référence vers un TableBlock et ses colonnes.\n\n    Données (data) :\n        table_block_id: id du TableBlock source (ou None si non configuré).\n        label_column_id: id de la colonne utilisée comme libellé de ligne.\n        date_column_id: id de la colonne Date utilisée pour les barres.\n    """\n\n    def __init__(\n        self,\n        table_block_id: Optional[str] = None,\n        label_column_id: Optional[str] = None,\n        date_column_id: Optional[str] = None,\n        id: str | None = None,\n    ) -> None:\n        super().__init__(\n            type=GANTT_BLOCK_TYPE,\n            data={\n                "table_block_id": table_block_id,\n                "label_column_id": label_column_id,\n                "date_column_id": date_column_id,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def table_block_id(self) -> Optional[str]:\n        return self.data.get("table_block_id")\n\n    @property\n    def label_column_id(self) -> Optional[str]:\n        return self.data.get("label_column_id")\n\n    @property\n    def date_column_id(self) -> Optional[str]:\n        return self.data.get("date_column_id")\n\n    def set_source(\n        self,\n        table_block_id: Optional[str],\n        label_column_id: Optional[str] = None,\n        date_column_id: Optional[str] = None,\n    ) -> None:\n        """Configure (ou reconfigure) la source du Gantt."""\n        self.data["table_block_id"] = table_block_id\n        self.data["label_column_id"] = label_column_id\n        self.data["date_column_id"] = date_column_id\n\n\ndef find_source_table(document, gantt_block: GanttBlock) -> Optional[TableBlock]:\n    """Retrouve le TableBlock référencé par le Gantt dans le document courant."""\n    if gantt_block.table_block_id is None:\n        return None\n    block = document.find_block(gantt_block.table_block_id)\n    return block if isinstance(block, TableBlock) else None\n\n\ndef available_date_columns(table: TableBlock) -> list[dict[str, Any]]:\n    """Colonnes "Date" utilisables comme source de barres du Gantt."""\n    return [column for column in table.columns if column["type"] == COLUMN_TYPE_DATE]\n\n\ndef _default_label_column(table: TableBlock) -> Optional[dict[str, Any]]:\n    for column in table.columns:\n        if column["type"] == COLUMN_TYPE_TEXT:\n            return column\n    return table.columns[0] if table.columns else None\n\n\ndef compute_gantt_rows(document, gantt_block: GanttBlock) -> list[dict[str, Any]]:\n    """Recalcule les lignes du Gantt à partir de l\'état actuel du document.\n\n    Ne lit ni ne modifie aucune donnée propre au GanttBlock : tout vient\n    du TableBlock référencé, relu à chaque appel (PATCH 19).\n\n    Retourne une liste de {"row_id", "label", "start", "end"} ("start"/\n    "end" sont des chaînes ISO "AAAA-MM-JJ", ou None si non renseignées).\n    """\n    table = find_source_table(document, gantt_block)\n    if table is None:\n        return []\n\n    label_column = table._find_column(gantt_block.label_column_id) if gantt_block.label_column_id else None\n    if label_column is None:\n        label_column = _default_label_column(table)\n\n    date_column = table._find_column(gantt_block.date_column_id) if gantt_block.date_column_id else None\n    if date_column is None or date_column["type"] != COLUMN_TYPE_DATE:\n        return []\n\n    rows: list[dict[str, Any]] = []\n    for row in table.rows:\n        label = str(row["cells"].get(label_column["id"], "")) if label_column else ""\n        date_value = row["cells"].get(date_column["id"])\n        if date_column.get("range"):\n            start = (date_value or {}).get("start") or None\n            end = (date_value or {}).get("end") or None\n        else:\n            start = date_value or None\n            end = start\n        rows.append({"row_id": row["id"], "label": label, "start": start, "end": end})\n    return rows\n'
_SOURCES['blocks.heading_block'] = '"""\nBlocs Titre (Heading).\n\nVariantes du bloc texte pour les titres H1, H2 et H3.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nHEADING_TYPES = {1: "heading1", 2: "heading2", 3: "heading3"}\n\n\nclass HeadingBlock(Block):\n    """Bloc de titre (H1, H2 ou H3).\n\n    Le niveau (1, 2 ou 3) détermine le type de bloc et sa taille\n    d\'affichage. Le contenu reste éditable comme un bloc texte.\n    """\n\n    def __init__(self, level: int = 1, content: str = "", id: str | None = None) -> None:\n        if level not in HEADING_TYPES:\n            raise ValueError("Le niveau de titre doit être 1, 2 ou 3.")\n        super().__init__(\n            type=HEADING_TYPES[level],\n            data={"content": content, "level": level},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def level(self) -> int:\n        return self.data.get("level", 1)\n\n    @property\n    def content(self) -> str:\n        return self.data.get("content", "")\n\n    @content.setter\n    def content(self, value: str) -> None:\n        self.data["content"] = value\n'
_SOURCES['blocks.image_block'] = '"""\nBloc Image.\n\nL\'image est stockée encodée en base64 directement dans les données\ndu bloc, afin d\'être incluse telle quelle dans la sauvegarde JSON\n(PATCH 8/9) sans fichier annexe à gérer séparément.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Optional\n\nfrom core.block import Block\n\nIMAGE_BLOCK_TYPE = "image"\n\n\nclass ImageBlock(Block):\n    """Bloc contenant une image redimensionnable.\n\n    Données (data) :\n        image_base64: contenu binaire de l\'image, encodé en base64.\n        format: extension/format d\'origine (png, jpg, ...).\n        width: largeur d\'affichage en pixels (None = taille native).\n    """\n\n    def __init__(\n        self,\n        image_base64: str = "",\n        image_format: str = "png",\n        width: Optional[int] = None,\n        id: str | None = None,\n    ) -> None:\n        super().__init__(\n            type=IMAGE_BLOCK_TYPE,\n            data={\n                "image_base64": image_base64,\n                "format": image_format,\n                "width": width,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def image_base64(self) -> str:\n        return self.data.get("image_base64", "")\n\n    @property\n    def image_format(self) -> str:\n        return self.data.get("format", "png")\n\n    @property\n    def width(self) -> Optional[int]:\n        return self.data.get("width")\n\n    @width.setter\n    def width(self, value: Optional[int]) -> None:\n        self.data["width"] = value\n'
_SOURCES['blocks.line_chart_block'] = '"""\nBloc "Courbes" (PATCH 47, révisé PATCH 52).\n\nTrace une ou plusieurs droites passant par l\'origine (y = pente * x)\nsur un même repère. Chaque série a sa pente définie soit\nmanuellement (constante éditable — couvre par exemple "idéal"\ny = x avec une pente de 1, ou une "vélocité" arbitraire), soit\ncalculée automatiquement à partir d\'un bloc "Planning par\ndépendances" (ratio durée planifiée / (durée planifiée + retard),\nvoir compute_efficiency_ratio) — ce qui couvre le besoin d\'une droite\nde "vélocité réelle" recalculée à chaque modification du planning.\n\nPATCH 52 : chaque droite est désormais tracée jusqu\'à ce qu\'elle\natteigne la même hauteur maximale (`y_scale`, la hauteur "carrée" de\nla droite "idéal" y=x) plutôt que jusqu\'à une abscisse commune : des\npentes différentes se terminent donc à des abscisses différentes\n(la zone de tracé s\'élargit en rectangle plutôt que de rester\ncarrée), ce qui évite que les droites et leurs étiquettes se\nsuperposent. `x_axis_label`/`y_axis_label` nomment les axes,\néditables au clic comme le titre.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any, Optional\n\nfrom blocks.dependency_gantt_block import DependencyGanttBlock, compute_efficiency_ratio\nfrom core.block import Block\n\nLINE_CHART_BLOCK_TYPE = "line_chart"\n\nSLOPE_MODE_CONSTANT = "constant"\nSLOPE_MODE_EFFICIENCY = "efficiency"\n\n_DEFAULT_COLORS = ["#1976d2", "#e53935", "#43a047", "#fb8c00", "#8e24aa"]\n\n\nclass LineChartBlock(Block):\n    """Bloc graphique en courbes.\n\n    Données (data) :\n        title: titre affiché au-dessus du graphique.\n        x_axis_label / y_axis_label: noms des axes (PATCH 52).\n        x_max: hauteur de référence (voir y_scale) — utilisée comme\n            échelle verticale carrée pour la droite "idéal" y=x.\n        series: liste de {\n            id, name, color,\n            mode: "constant" | "efficiency",\n            slope: pente utilisée si mode == "constant",\n            source_block_id: id d\'un DependencyGanttBlock utilisé si\n                mode == "efficiency" (la pente est alors recalculée à\n                chaque lecture, jamais stockée),\n        }\n    """\n\n    def __init__(\n        self,\n        title: str = "",\n        x_axis_label: str = "",\n        y_axis_label: str = "",\n        x_max: float = 10.0,\n        series: list[dict[str, Any]] | None = None,\n        id: str | None = None,\n    ) -> None:\n        normalized_series: list[dict[str, Any]] = []\n        for s in series or []:\n            normalized_series.append({**s, "id": s.get("id") or str(uuid.uuid4())})\n        super().__init__(\n            type=LINE_CHART_BLOCK_TYPE,\n            data={\n                "title": title,\n                "x_axis_label": x_axis_label,\n                "y_axis_label": y_axis_label,\n                "x_max": x_max,\n                "series": normalized_series,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def title(self) -> str:\n        return self.data.get("title", "")\n\n    @title.setter\n    def title(self, value: str) -> None:\n        self.data["title"] = value\n\n    @property\n    def x_axis_label(self) -> str:\n        return self.data.get("x_axis_label", "")\n\n    @x_axis_label.setter\n    def x_axis_label(self, value: str) -> None:\n        self.data["x_axis_label"] = value\n\n    @property\n    def y_axis_label(self) -> str:\n        return self.data.get("y_axis_label", "")\n\n    @y_axis_label.setter\n    def y_axis_label(self, value: str) -> None:\n        self.data["y_axis_label"] = value\n\n    @property\n    def x_max(self) -> float:\n        return float(self.data.get("x_max", 10.0))\n\n    @x_max.setter\n    def x_max(self, value: float) -> None:\n        self.data["x_max"] = max(float(value), 0.01)\n\n    @property\n    def series(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("series", [])\n\n    def _find_series(self, series_id: str) -> Optional[dict[str, Any]]:\n        for s in self.series:\n            if s["id"] == series_id:\n                return s\n        return None\n\n    def add_series(\n        self,\n        name: str = "Série",\n        mode: str = SLOPE_MODE_CONSTANT,\n        slope: float = 1.0,\n        source_block_id: Optional[str] = None,\n        color: Optional[str] = None,\n    ) -> dict[str, Any]:\n        s = {\n            "id": str(uuid.uuid4()),\n            "name": name,\n            "color": color or _DEFAULT_COLORS[len(self.series) % len(_DEFAULT_COLORS)],\n            "mode": mode if mode in (SLOPE_MODE_CONSTANT, SLOPE_MODE_EFFICIENCY) else SLOPE_MODE_CONSTANT,\n            "slope": float(slope),\n            "source_block_id": source_block_id,\n        }\n        self.series.append(s)\n        return s\n\n    def remove_series(self, series_id: str) -> bool:\n        s = self._find_series(series_id)\n        if s is None:\n            return False\n        self.series.remove(s)\n        return True\n\n    def set_series_name(self, series_id: str, name: str) -> bool:\n        s = self._find_series(series_id)\n        if s is None:\n            return False\n        s["name"] = name\n        return True\n\n    def set_series_slope(self, series_id: str, slope: float) -> bool:\n        s = self._find_series(series_id)\n        if s is None:\n            return False\n        s["slope"] = float(slope)\n        return True\n\n    def set_series_mode(self, series_id: str, mode: str, source_block_id: Optional[str] = None) -> bool:\n        s = self._find_series(series_id)\n        if s is None or mode not in (SLOPE_MODE_CONSTANT, SLOPE_MODE_EFFICIENCY):\n            return False\n        s["mode"] = mode\n        s["source_block_id"] = source_block_id\n        return True\n\n\ndef resolve_series_slope(document, series: dict[str, Any]) -> float:\n    """Pente effective d\'une série : constante, ou recalculée depuis un\n    bloc de planning (0.0 si la source n\'est pas/plus valide)."""\n    if series["mode"] != SLOPE_MODE_EFFICIENCY:\n        return float(series.get("slope", 0.0))\n    source = document.find_block(series.get("source_block_id"))\n    if not isinstance(source, DependencyGanttBlock):\n        return 0.0\n    ratio = compute_efficiency_ratio(document, source)\n    return ratio if ratio is not None else 0.0\n\n\ndef compute_line_series(document, block: LineChartBlock) -> list[dict[str, Any]]:\n    """Retourne, pour chaque série, {id, name, color, slope, x0, y0, x1, y1}\n    prêt à être tracé.\n\n    PATCH 52 — toutes les droites visent la même hauteur maximale\n    `y_scale` (= block.x_max, la hauteur de la droite "idéal" y=x) :\n    chacune s\'arrête à l\'abscisse où elle atteint cette hauteur\n    (x1 = y_scale / pente), donc des pentes différentes se terminent\n    à des abscisses différentes plutôt que de se superposer au même\n    point. Une pente nulle ou négative n\'atteint jamais y_scale ; on\n    la trace alors à plat sur toute la largeur de référence.\n    """\n    y_scale = block.x_max\n    result = []\n    for s in block.series:\n        slope = resolve_series_slope(document, s)\n        if slope > 0:\n            x1 = y_scale / slope\n            y1 = y_scale\n        else:\n            x1 = block.x_max\n            y1 = slope * x1\n        result.append(\n            {\n                "id": s["id"],\n                "name": s["name"],\n                "color": s["color"],\n                "slope": slope,\n                "x0": 0.0,\n                "y0": 0.0,\n                "x1": x1,\n                "y1": y1,\n            }\n        )\n    return result\n'
_SOURCES['blocks.linked_checklist_block'] = '"""\nBloc "Checklists liées" (PATCH 44).\n\nDeux checklists côte à côte séparées par un séparateur ajustable :\nà gauche les éléments non cochés ("à faire"), à droite les éléments\ncochés ("faites"). Cocher un élément le fait basculer du panneau\ngauche vers le panneau droit ; le décocher le fait revenir à gauche.\n\nContrairement à ChecklistBlock (une seule liste triée), les éléments\nsont ici répartis entre deux panneaux visuellement distincts, d\'où\nun stockage dédié plutôt qu\'une réutilisation directe.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any\n\nfrom core.block import Block\n\nLINKED_CHECKLIST_BLOCK_TYPE = "linked_checklist"\n\n\nclass LinkedChecklistBlock(Block):\n    """Bloc de deux checklists liées par l\'état coché de leurs éléments.\n\n    Données (data) :\n        items: liste de {"id": str, "text": str, "checked": bool}.\n        split: position (0..1) du séparateur ajustable entre panneaux.\n    """\n\n    def __init__(\n        self,\n        items: list[dict[str, Any]] | None = None,\n        split: float = 0.5,\n        id: str | None = None,\n    ) -> None:\n        normalized_items: list[dict[str, Any]] = []\n        for item in items or []:\n            normalized_items.append({**item, "id": item.get("id") or str(uuid.uuid4())})\n\n        super().__init__(\n            type=LINKED_CHECKLIST_BLOCK_TYPE,\n            data={"items": normalized_items, "split": split},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def items(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("items", [])\n\n    @property\n    def split(self) -> float:\n        return float(self.data.get("split", 0.5))\n\n    @split.setter\n    def split(self, value: float) -> None:\n        self.data["split"] = max(0.05, min(0.95, value))\n\n    def _find_item(self, item_id: str) -> dict[str, Any] | None:\n        for item in self.items:\n            if item.get("id") == item_id:\n                return item\n        return None\n\n    def add_item(self, text: str = "", checked: bool = False) -> dict[str, Any]:\n        """Ajoute un élément (toujours côté "à faire" par défaut) et le retourne."""\n        item = {"id": str(uuid.uuid4()), "text": text, "checked": checked}\n        self.items.append(item)\n        return item\n\n    def remove_item(self, item_id: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        self.items.remove(item)\n        return True\n\n    def set_item_text(self, item_id: str, text: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        item["text"] = text\n        return True\n\n    def set_item_checked(self, item_id: str, checked: bool) -> bool:\n        """Coche/décoche un élément (le fait ainsi changer de panneau)."""\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        item["checked"] = checked\n        return True\n\n    def todo_items(self) -> list[dict[str, Any]]:\n        """Éléments du panneau gauche ("à faire")."""\n        return [item for item in self.items if not item.get("checked", False)]\n\n    def done_items(self) -> list[dict[str, Any]]:\n        """Éléments du panneau droit ("faites")."""\n        return [item for item in self.items if item.get("checked", False)]\n'
_SOURCES['blocks.list_block'] = '"""\nBloc Liste (PATCH 23) : liste à puces ou numérotée.\n\nChaque élément possède un texte ; l\'ordre est significatif. Le style\n("bullet" ou "numbered") est une propriété du bloc entier, modifiable\nà tout moment sans perdre les éléments.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any\n\nfrom core.block import Block\n\nLIST_BLOCK_TYPE = "list"\n\nLIST_TYPE_BULLET = "bullet"\nLIST_TYPE_NUMBERED = "numbered"\nLIST_TYPES = [LIST_TYPE_BULLET, LIST_TYPE_NUMBERED]\n\n\nclass ListBlock(Block):\n    """Bloc de liste (à puces ou numérotée).\n\n    Données (data) :\n        list_type: "bullet" ou "numbered".\n        items: liste de {"id": str, "text": str}, ordre significatif.\n    """\n\n    def __init__(\n        self,\n        items: list[dict[str, Any]] | None = None,\n        list_type: str = LIST_TYPE_BULLET,\n        id: str | None = None,\n    ) -> None:\n        normalized_items: list[dict[str, Any]] = [\n            {"id": item.get("id") or str(uuid.uuid4()), "text": item.get("text", "")}\n            for item in items or []\n        ]\n        super().__init__(\n            type=LIST_BLOCK_TYPE,\n            data={\n                "list_type": list_type if list_type in LIST_TYPES else LIST_TYPE_BULLET,\n                "items": normalized_items,\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def items(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("items", [])\n\n    @property\n    def list_type(self) -> str:\n        return self.data.get("list_type", LIST_TYPE_BULLET)\n\n    def set_list_type(self, list_type: str) -> bool:\n        if list_type not in LIST_TYPES:\n            return False\n        self.data["list_type"] = list_type\n        return True\n\n    def _find_item(self, item_id: str) -> dict[str, Any] | None:\n        for item in self.items:\n            if item.get("id") == item_id:\n                return item\n        return None\n\n    def add_item(self, text: str = "", index: int | None = None) -> dict[str, Any]:\n        """Ajoute un élément (à la fin, ou à `index` si fourni) et le retourne."""\n        item = {"id": str(uuid.uuid4()), "text": text}\n        if index is None:\n            self.items.append(item)\n        else:\n            self.items.insert(index, item)\n        return item\n\n    def remove_item(self, item_id: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        self.items.remove(item)\n        return True\n\n    def set_item_text(self, item_id: str, text: str) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        item["text"] = text\n        return True\n\n    def move_item(self, item_id: str, new_index: int) -> bool:\n        item = self._find_item(item_id)\n        if item is None:\n            return False\n        self.items.remove(item)\n        new_index = max(0, min(new_index, len(self.items)))\n        self.items.insert(new_index, item)\n        return True\n'
_SOURCES['blocks.people_list_block'] = '"""\nBloc "Effectif" (PATCH 52).\n\nContrairement aux autres blocs, ce bloc n\'a aucune donnée propre : il\naffiche et permet d\'éditer directement le registre partagé de\npersonnes du document (Document.people), le même registre que celui\nutilisé par le Gestionnaire de personnes (Édition > Gestionnaire de\npersonnes) et par les colonnes "Personne" des blocs Tableau. Ajouter\nune personne ici, ou depuis le Gestionnaire, les rend donc immédiatement\nvisibles partout ailleurs : il n\'y a qu\'une seule source de vérité.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nPEOPLE_LIST_BLOCK_TYPE = "people_list"\n\n\nclass PeopleListBlock(Block):\n    """Bloc sans donnée propre : simple point d\'affichage/édition du\n    registre partagé Document.people."""\n\n    def __init__(self, id: str | None = None) -> None:\n        super().__init__(type=PEOPLE_LIST_BLOCK_TYPE, data={}, id=id or str(uuid.uuid4()))\n'
_SOURCES['blocks.quote_block'] = '"""\nBloc Citation (PATCH 21).\n\nVariante simple du bloc texte : un unique champ `content`, affiché\navec une mise en forme dédiée (barre verticale, italique) plutôt que\nstocké en HTML riche comme TextBlock.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nQUOTE_BLOCK_TYPE = "quote"\n\n\nclass QuoteBlock(Block):\n    """Bloc citation : texte libre affiché avec une mise en forme dédiée."""\n\n    def __init__(self, content: str = "", id: str | None = None) -> None:\n        super().__init__(\n            type=QUOTE_BLOCK_TYPE,\n            data={"content": content},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def content(self) -> str:\n        return self.data.get("content", "")\n\n    @content.setter\n    def content(self, value: str) -> None:\n        self.data["content"] = value\n'
_SOURCES['blocks.registry'] = '"""\nRegistre de reconstruction des blocs (PATCH 8 / PATCH 9).\n\nFait le lien entre le type stocké dans le JSON et la classe de bloc\nconcrète à instancier. Chaque nouveau type de bloc (checklist, image,\ntableau, ...) devra enregistrer sa propre reconstruction ici.\n"""\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom blocks.checklist_block import CHECKLIST_BLOCK_TYPE, ChecklistBlock\nfrom blocks.code_block import CODE_BLOCK_TYPE, CodeBlock\nfrom blocks.bar_chart_block import BAR_CHART_BLOCK_TYPE, BarChartBlock\nfrom blocks.dependency_gantt_block import DEPENDENCY_GANTT_BLOCK_TYPE, DependencyGanttBlock\nfrom blocks.formula_block import FORMULA_BLOCK_TYPE, FormulaBlock\nfrom blocks.gantt_block import GANTT_BLOCK_TYPE, GanttBlock\nfrom blocks.heading_block import HEADING_TYPES, HeadingBlock\nfrom blocks.image_block import IMAGE_BLOCK_TYPE, ImageBlock\nfrom blocks.linked_checklist_block import LINKED_CHECKLIST_BLOCK_TYPE, LinkedChecklistBlock\nfrom blocks.line_chart_block import LINE_CHART_BLOCK_TYPE, LineChartBlock\nfrom blocks.list_block import LIST_BLOCK_TYPE, ListBlock\nfrom blocks.people_list_block import PEOPLE_LIST_BLOCK_TYPE, PeopleListBlock\nfrom blocks.quote_block import QUOTE_BLOCK_TYPE, QuoteBlock\nfrom blocks.separator_block import SEPARATOR_BLOCK_TYPE, SeparatorBlock\nfrom blocks.simple_table_block import SIMPLE_TABLE_BLOCK_TYPE, SimpleTableBlock\nfrom blocks.table_block import TABLE_BLOCK_TYPE, TableBlock\nfrom blocks.text_block import TEXT_BLOCK_TYPE, TextBlock\nfrom core.block import Block\n\n_LEVEL_BY_TYPE = {value: key for key, value in HEADING_TYPES.items()}\n\n\ndef block_from_dict(raw: dict[str, Any]) -> Block:\n    """Reconstruit un bloc concret à partir de son dictionnaire JSON.\n\n    Raises:\n        ValueError: si le type de bloc n\'est pas reconnu.\n    """\n    block_type = raw["type"]\n    data = raw.get("data", {})\n    block_id = raw["id"]\n\n    if block_type == TEXT_BLOCK_TYPE:\n        return TextBlock(\n            content=data.get("content", ""),\n            html=data.get("html", ""),\n            id=block_id,\n        )\n\n    if block_type == CHECKLIST_BLOCK_TYPE:\n        return ChecklistBlock(items=data.get("items", []), id=block_id)\n\n    if block_type == LINKED_CHECKLIST_BLOCK_TYPE:\n        return LinkedChecklistBlock(\n            items=data.get("items", []), split=data.get("split", 0.5), id=block_id\n        )\n\n    if block_type == IMAGE_BLOCK_TYPE:\n        return ImageBlock(\n            image_base64=data.get("image_base64", ""),\n            image_format=data.get("format", "png"),\n            width=data.get("width"),\n            id=block_id,\n        )\n\n    if block_type == TABLE_BLOCK_TYPE:\n        return TableBlock(\n            columns=data.get("columns", []),\n            rows=data.get("rows", []),\n            manual_merges=data.get("manual_merges", {}),\n            id=block_id,\n        )\n\n    if block_type == GANTT_BLOCK_TYPE:\n        return GanttBlock(\n            table_block_id=data.get("table_block_id"),\n            label_column_id=data.get("label_column_id"),\n            date_column_id=data.get("date_column_id"),\n            id=block_id,\n        )\n\n    if block_type == FORMULA_BLOCK_TYPE:\n        return FormulaBlock(\n            table_block_id=data.get("table_block_id"),\n            number_column_id=data.get("number_column_id"),\n            boolean_column_id=data.get("boolean_column_id"),\n            label=data.get("label", "Résultat: "),\n            id=block_id,\n        )\n\n    if block_type == DEPENDENCY_GANTT_BLOCK_TYPE:\n        return DependencyGanttBlock(\n            table_block_id=data.get("table_block_id"),\n            label_column_id=data.get("label_column_id"),\n            person_column_id=data.get("person_column_id"),\n            duration_column_id=data.get("duration_column_id"),\n            risk_column_id=data.get("risk_column_id"),\n            dependency_column_id=data.get("dependency_column_id"),\n            delta_column_id=data.get("delta_column_id"),\n            deltas=data.get("deltas", {}),\n            time_unit=data.get("time_unit", "jours"),\n            id=block_id,\n        )\n\n    if block_type == LINE_CHART_BLOCK_TYPE:\n        return LineChartBlock(\n            title=data.get("title", ""),\n            x_axis_label=data.get("x_axis_label", ""),\n            y_axis_label=data.get("y_axis_label", ""),\n            x_max=data.get("x_max", 10.0),\n            series=data.get("series", []),\n            id=block_id,\n        )\n\n    if block_type == BAR_CHART_BLOCK_TYPE:\n        return BarChartBlock(\n            title=data.get("title", "Graphique"),\n            y_axis_label=data.get("y_axis_label", ""),\n            source_gantt_id=data.get("source_gantt_id"),\n            group_column_id=data.get("group_column_id"),\n            value_column_id=data.get("value_column_id"),\n            actual_column_id=data.get("actual_column_id"),\n            id=block_id,\n        )\n\n    if block_type == SIMPLE_TABLE_BLOCK_TYPE:\n        return SimpleTableBlock(rows=data.get("rows", []), id=block_id)\n\n    if block_type == SEPARATOR_BLOCK_TYPE:\n        return SeparatorBlock(id=block_id)\n\n    if block_type == CODE_BLOCK_TYPE:\n        return CodeBlock(content=data.get("content", ""), language=data.get("language", "text"), id=block_id)\n\n    if block_type == LIST_BLOCK_TYPE:\n        return ListBlock(\n            items=data.get("items", []),\n            list_type=data.get("list_type", "bullet"),\n            id=block_id,\n        )\n\n    if block_type == PEOPLE_LIST_BLOCK_TYPE:\n        return PeopleListBlock(id=block_id)\n\n    if block_type == QUOTE_BLOCK_TYPE:\n        return QuoteBlock(content=data.get("content", ""), id=block_id)\n\n    if block_type in _LEVEL_BY_TYPE:\n        return HeadingBlock(\n            level=_LEVEL_BY_TYPE[block_type],\n            content=data.get("content", ""),\n            id=block_id,\n        )\n\n    raise ValueError(f"Type de bloc inconnu dans le fichier : {block_type!r}")\n'
_SOURCES['blocks.separator_block'] = '"""\nBloc Séparateur (PATCH 20).\n\nLigne horizontale purement visuelle, sans contenu ni interaction :\nelle sert uniquement à structurer visuellement le document.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nSEPARATOR_BLOCK_TYPE = "separator"\n\n\nclass SeparatorBlock(Block):\n    """Bloc séparateur : aucune donnée, juste un marqueur de type."""\n\n    def __init__(self, id: str | None = None) -> None:\n        super().__init__(type=SEPARATOR_BLOCK_TYPE, data={}, id=id or str(uuid.uuid4()))\n'
_SOURCES['blocks.simple_table_block'] = '"""\nBloc Tableau simple (PATCH 24).\n\nContrairement au bloc Tableau du PATCH 14 (colonnes typées, id\nstables par colonne/ligne, pensé comme une mini base de données), ce\nbloc est une grille de texte légère et purement positionnelle : une\nliste de lignes, chaque ligne étant une liste de chaînes de même\nlongueur. Aucun typage, aucune option, aucune id par cellule —\nvolontairement indépendant du moteur du PATCH 14.\n\nAdapté à un simple tableau de mise en page (ex. copier/coller un\npetit tableau markdown), pas à une base de données.\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nSIMPLE_TABLE_BLOCK_TYPE = "simple_table"\n\n\ndef _rectangularize(rows: list[list[str]]) -> list[list[str]]:\n    """Complète les lignes trop courtes avec des cellules vides pour\n    garantir une grille rectangulaire (nombre de colonnes uniforme)."""\n    width = max((len(row) for row in rows), default=0)\n    return [list(row) + [""] * (width - len(row)) for row in rows]\n\n\nclass SimpleTableBlock(Block):\n    """Grille de texte simple.\n\n    Données (data) :\n        rows: liste de lignes, chaque ligne étant une liste de\n            chaînes (une par colonne). Toutes les lignes ont la même\n            longueur (garanti par `_rectangularize`).\n    """\n\n    def __init__(\n        self,\n        rows: list[list[str]] | None = None,\n        row_count: int = 2,\n        column_count: int = 2,\n        id: str | None = None,\n    ) -> None:\n        if rows is None:\n            rows = [["" for _ in range(column_count)] for _ in range(row_count)]\n        super().__init__(\n            type=SIMPLE_TABLE_BLOCK_TYPE,\n            data={"rows": _rectangularize(rows)},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def rows(self) -> list[list[str]]:\n        return self.data.setdefault("rows", [])\n\n    @property\n    def row_count(self) -> int:\n        return len(self.rows)\n\n    @property\n    def column_count(self) -> int:\n        return len(self.rows[0]) if self.rows else 0\n\n    def get_cell(self, row_index: int, column_index: int) -> str:\n        return self.rows[row_index][column_index]\n\n    def set_cell(self, row_index: int, column_index: int, text: str) -> bool:\n        if not (0 <= row_index < self.row_count and 0 <= column_index < self.column_count):\n            return False\n        self.rows[row_index][column_index] = text\n        return True\n\n    def add_row(self, index: int | None = None) -> None:\n        new_row = ["" for _ in range(self.column_count)]\n        if index is None:\n            self.rows.append(new_row)\n        else:\n            self.rows.insert(max(0, min(index, self.row_count)), new_row)\n\n    def remove_row(self, index: int) -> bool:\n        if not (0 <= index < self.row_count):\n            return False\n        del self.rows[index]\n        return True\n\n    def add_column(self, index: int | None = None) -> None:\n        col_index = self.column_count if index is None else max(0, min(index, self.column_count))\n        for row in self.rows:\n            row.insert(col_index, "")\n\n    def remove_column(self, index: int) -> bool:\n        if not (0 <= index < self.column_count):\n            return False\n        for row in self.rows:\n            del row[index]\n        return True\n'
_SOURCES['blocks.table_block'] = '"""\nBloc Tableau — moteur (PATCH 14) + colonnes typées (PATCH 15).\n\nUn tableau est composé de colonnes (ordonnées) et de lignes\n(ordonnées). Chaque ligne stocke ses valeurs dans un dictionnaire\n{column_id: valeur}, ce qui permet d\'ajouter/supprimer/déplacer une\ncolonne sans avoir à réindexer toutes les lignes.\n\nChaque colonne possède un type fixe (PATCH 15) qui détermine la\nforme de la valeur stockée dans les cellules correspondantes :\n    - text / number : chaîne de caractères.\n    - date : chaîne ISO "AAAA-MM-JJ" (ou ""), ou {"start": ..., "end": ...}\n      si la colonne est configurée en plage (PATCH 18, voir "range").\n    - duration : {"amount": int, "unit": "heures"|"jours"|"semaines"}.\n    - boolean : bool.\n    - person : liste de noms (str).\n    - select : chaîne parmi column["options"] (ou "").\n    - multi_select : liste de chaînes parmi column["options"].\n    - checklist : liste de {"id": str, "text": str, "checked": bool}.\n\nLes vues dérivées (Gantt, PATCH 19) et les gestionnaires dédiés\n(Personne PATCH 16, Durée PATCH 17, plages de dates PATCH 18)\ns\'appuieront sur ce typage sans changer la structure de base posée ici.\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any\n\nfrom core.block import Block\n\nTABLE_BLOCK_TYPE = "table"\n\nCOLUMN_TYPE_TEXT = "text"\nCOLUMN_TYPE_NUMBER = "number"\nCOLUMN_TYPE_DATE = "date"\nCOLUMN_TYPE_DURATION = "duration"\nCOLUMN_TYPE_BOOLEAN = "boolean"\nCOLUMN_TYPE_PERSON = "person"\nCOLUMN_TYPE_SELECT = "select"\nCOLUMN_TYPE_MULTI_SELECT = "multi_select"\nCOLUMN_TYPE_CHECKLIST = "checklist"\n\nCOLUMN_TYPES: list[str] = [\n    COLUMN_TYPE_TEXT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_DATE,\n    COLUMN_TYPE_DURATION,\n    COLUMN_TYPE_BOOLEAN,\n    COLUMN_TYPE_PERSON,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_CHECKLIST,\n]\n\nCOLUMN_TYPE_LABELS: dict[str, str] = {\n    COLUMN_TYPE_TEXT: "Texte",\n    COLUMN_TYPE_NUMBER: "Nombre",\n    COLUMN_TYPE_DATE: "Date",\n    COLUMN_TYPE_DURATION: "Durée",\n    COLUMN_TYPE_BOOLEAN: "Booléen",\n    COLUMN_TYPE_PERSON: "Personne",\n    COLUMN_TYPE_SELECT: "Liste",\n    COLUMN_TYPE_MULTI_SELECT: "Liste multiple",\n    COLUMN_TYPE_CHECKLIST: "Checklist",\n}\n\nDURATION_UNITS: list[str] = ["heures", "jours", "semaines"]\n\n\ndef default_value_for_column(column: dict) -> Any:\n    """Valeur par défaut d\'une cellule neuve, selon le type (et les\n    options, ex. plage de dates) de sa colonne."""\n    col_type = column.get("type") if isinstance(column, dict) else column\n    if col_type == COLUMN_TYPE_BOOLEAN:\n        return False\n    if col_type == COLUMN_TYPE_DURATION:\n        return {"amount": 0, "unit": DURATION_UNITS[1]}\n    if col_type == COLUMN_TYPE_DATE and isinstance(column, dict) and column.get("range"):\n        return {"start": "", "end": ""}\n    if col_type in (COLUMN_TYPE_PERSON, COLUMN_TYPE_MULTI_SELECT, COLUMN_TYPE_CHECKLIST):\n        return []\n    return ""\n\n\n# Alias rétrocompatible : appelable avec un simple type (sans plage).\ndef default_value_for_type(col_type: str) -> Any:\n    return default_value_for_column({"type": col_type})\n\n\ndef _normalize_value_for_column(column: dict, value: Any) -> Any:\n    """Ramène une valeur potentiellement invalide/absente à une forme\n    cohérente avec le type (et les options) de la colonne."""\n    col_type = column["type"]\n    if col_type == COLUMN_TYPE_BOOLEAN:\n        return bool(value)\n    if col_type == COLUMN_TYPE_DATE:\n        if column.get("range"):\n            if isinstance(value, dict):\n                return {"start": value.get("start") or "", "end": value.get("end") or ""}\n            return {"start": "", "end": ""}\n        return value if isinstance(value, str) else ""\n    if col_type == COLUMN_TYPE_DURATION:\n        if isinstance(value, dict):\n            unit = value.get("unit") if value.get("unit") in DURATION_UNITS else DURATION_UNITS[1]\n            try:\n                amount = int(value.get("amount", 0))\n            except (TypeError, ValueError):\n                amount = 0\n            return {"amount": amount, "unit": unit}\n        return default_value_for_column(column)\n    if col_type in (COLUMN_TYPE_PERSON, COLUMN_TYPE_MULTI_SELECT):\n        return list(value) if isinstance(value, list) else []\n    if col_type == COLUMN_TYPE_CHECKLIST:\n        items = value if isinstance(value, list) else []\n        return [\n            {\n                "id": item.get("id") or str(uuid.uuid4()),\n                "text": item.get("text", ""),\n                "checked": bool(item.get("checked", False)),\n            }\n            for item in items\n            if isinstance(item, dict)\n        ]\n    return value if value is not None else ""\n\n\nclass TableBlock(Block):\n    """Bloc tableau.\n\n    Données (data) :\n        columns: liste de {"id": str, "name": str, "type": str, "options": list[str]}.\n        rows: liste de {"id": str, "cells": {column_id: valeur}}.\n    """\n\n    def __init__(\n        self,\n        columns: list[dict[str, Any]] | None = None,\n        rows: list[dict[str, Any]] | None = None,\n        manual_merges: dict[str, list[list[str]]] | None = None,\n        id: str | None = None,\n    ) -> None:\n        normalized_columns: list[dict[str, Any]] = []\n        for column in columns or []:\n            col_type = column.get("type") if column.get("type") in COLUMN_TYPES else COLUMN_TYPE_TEXT\n            normalized_columns.append(\n                {\n                    "id": column.get("id") or str(uuid.uuid4()),\n                    "name": column.get("name", ""),\n                    "type": col_type,\n                    "options": list(column.get("options", [])),\n                    "range": bool(column.get("range", False)) if col_type == COLUMN_TYPE_DATE else False,\n                    # PATCH 56 — unité affichée dans l\'en-tête ("j", "€", "%",\n                    # ...), pertinente uniquement pour une colonne "Nombre".\n                    "unit": str(column.get("unit", "")) if col_type == COLUMN_TYPE_NUMBER else "",\n                }\n            )\n        columns_by_id = {column["id"]: column for column in normalized_columns}\n\n        normalized_rows: list[dict[str, Any]] = []\n        for row in rows or []:\n            raw_cells = row.get("cells", {})\n            cells = {\n                column_id: _normalize_value_for_column(column, raw_cells.get(column_id))\n                for column_id, column in columns_by_id.items()\n            }\n            normalized_rows.append(\n                {"id": row.get("id") or str(uuid.uuid4()), "cells": cells}\n            )\n\n        super().__init__(\n            type=TABLE_BLOCK_TYPE,\n            data={\n                "columns": normalized_columns,\n                "rows": normalized_rows,\n                # PATCH 51 — fusion manuelle de cellules (indépendante des\n                # fusions automatiques par valeur identique) : {column_id:\n                # [[row_id, row_id, ...], ...]}, voir merge_cells/unmerge_cell.\n                "manual_merges": {\n                    column_id: [list(group) for group in groups]\n                    for column_id, groups in (manual_merges or {}).items()\n                },\n            },\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def columns(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("columns", [])\n\n    @property\n    def rows(self) -> list[dict[str, Any]]:\n        return self.data.setdefault("rows", [])\n\n    def _find_column(self, column_id: str) -> dict[str, Any] | None:\n        for column in self.columns:\n            if column.get("id") == column_id:\n                return column\n        return None\n\n    def _find_row(self, row_id: str) -> dict[str, Any] | None:\n        for row in self.rows:\n            if row.get("id") == row_id:\n                return row\n        return None\n\n    # -- Fusion manuelle de cellules (PATCH 51) -----------------------\n\n    def manual_merge_groups(self, column_id: str) -> list[list[str]]:\n        return self.data.get("manual_merges", {}).get(column_id, [])\n\n    def merge_cells(self, column_id: str, row_ids: list[str]) -> None:\n        """Fusionne visuellement les cellules de `column_id` pour les\n        lignes `row_ids` (fusionne aussi avec tout groupe existant qui\n        chevaucherait ces lignes). Ne modifie aucune valeur de cellule,\n        uniquement l\'affichage."""\n        merges = self.data.setdefault("manual_merges", {})\n        groups = merges.setdefault(column_id, [])\n        combined = set(row_ids)\n        remaining: list[list[str]] = []\n        for group in groups:\n            if combined.intersection(group):\n                combined.update(group)\n            else:\n                remaining.append(group)\n        order = {row["id"]: index for index, row in enumerate(self.rows)}\n        remaining.append(sorted(combined, key=lambda row_id: order.get(row_id, 0)))\n        merges[column_id] = remaining\n\n    def unmerge_cell(self, column_id: str, row_id: str) -> None:\n        """Retire `row_id` de son groupe de fusion manuelle sur\n        `column_id` (le groupe est supprimé s\'il ne reste plus qu\'une\n        ligne)."""\n        merges = self.data.get("manual_merges", {})\n        groups = merges.get(column_id)\n        if not groups:\n            return\n        new_groups = []\n        for group in groups:\n            if row_id in group:\n                filtered = [r for r in group if r != row_id]\n                if len(filtered) > 1:\n                    new_groups.append(filtered)\n            else:\n                new_groups.append(group)\n        merges[column_id] = new_groups\n\n    # -- Colonnes ----------------------------------------------------\n\n    def add_column(\n        self,\n        name: str = "",\n        col_type: str = COLUMN_TYPE_TEXT,\n        options: list[str] | None = None,\n        date_range: bool = False,\n        unit: str = "",\n        index: int | None = None,\n    ) -> dict[str, Any]:\n        """Ajoute une colonne typée et une cellule par défaut à chaque ligne.\n\n        `date_range` n\'a d\'effet que pour col_type == "date" (PATCH 18) :\n        la cellule stocke alors {"start", "end"} au lieu d\'une date seule.\n        `unit` (PATCH 56) n\'a d\'effet que pour col_type == "number" :\n        affichée dans l\'en-tête, ex. "j", "€", "%".\n        """\n        if col_type not in COLUMN_TYPES:\n            col_type = COLUMN_TYPE_TEXT\n        column = {\n            "id": str(uuid.uuid4()),\n            "name": name,\n            "type": col_type,\n            "options": list(options or []),\n            "range": bool(date_range) if col_type == COLUMN_TYPE_DATE else False,\n            "unit": str(unit) if col_type == COLUMN_TYPE_NUMBER else "",\n        }\n        if index is None:\n            self.columns.append(column)\n        else:\n            self.columns.insert(index, column)\n        for row in self.rows:\n            row["cells"][column["id"]] = default_value_for_column(column)\n        return column\n\n    def remove_column(self, column_id: str) -> bool:\n        column = self._find_column(column_id)\n        if column is None:\n            return False\n        self.columns.remove(column)\n        for row in self.rows:\n            row["cells"].pop(column_id, None)\n        return True\n\n    def rename_column(self, column_id: str, name: str) -> bool:\n        column = self._find_column(column_id)\n        if column is None:\n            return False\n        column["name"] = name\n        return True\n\n    def set_column_options(self, column_id: str, options: list[str]) -> bool:\n        """Définit les choix possibles d\'une colonne "Liste"/"Liste multiple".\n\n        Les cellules "select" dont la valeur n\'est plus dans les choix\n        sont réinitialisées ; pour "multi_select", seules les valeurs\n        encore valides sont conservées.\n        """\n        column = self._find_column(column_id)\n        if column is None:\n            return False\n        column["options"] = list(options)\n        if column["type"] == COLUMN_TYPE_SELECT:\n            for row in self.rows:\n                if row["cells"].get(column_id) not in column["options"]:\n                    row["cells"][column_id] = ""\n        elif column["type"] == COLUMN_TYPE_MULTI_SELECT:\n            for row in self.rows:\n                current = row["cells"].get(column_id) or []\n                row["cells"][column_id] = [v for v in current if v in column["options"]]\n        return True\n\n    def set_column_date_range(self, column_id: str, date_range: bool) -> bool:\n        """Bascule une colonne "Date" entre date unique et plage début/fin\n        (PATCH 18). Réinitialise les cellules à la valeur par défaut du\n        nouveau mode (les deux formats ne sont pas interchangeables)."""\n        column = self._find_column(column_id)\n        if column is None or column["type"] != COLUMN_TYPE_DATE:\n            return False\n        column["range"] = bool(date_range)\n        for row in self.rows:\n            row["cells"][column_id] = default_value_for_column(column)\n        return True\n\n    def set_column_unit(self, column_id: str, unit: str) -> bool:\n        """PATCH 56 — définit l\'unité affichée dans l\'en-tête d\'une colonne\n        "Nombre" (ex : "j", "€", "%"). Sans effet sur les autres types."""\n        column = self._find_column(column_id)\n        if column is None or column["type"] != COLUMN_TYPE_NUMBER:\n            return False\n        column["unit"] = str(unit)\n        return True\n\n    def move_column(self, column_id: str, new_index: int) -> bool:\n        column = self._find_column(column_id)\n        if column is None:\n            return False\n        self.columns.remove(column)\n        new_index = max(0, min(new_index, len(self.columns)))\n        self.columns.insert(new_index, column)\n        return True\n\n    # -- Lignes --------------------------------------------------------\n\n    def add_row(self, values: dict[str, Any] | None = None, index: int | None = None) -> dict[str, Any]:\n        """Ajoute une ligne. `values` est indexé par id de colonne."""\n        cells = {column["id"]: default_value_for_column(column) for column in self.columns}\n        cells.update({k: v for k, v in (values or {}).items() if k in cells})\n        row = {"id": str(uuid.uuid4()), "cells": cells}\n        if index is None:\n            self.rows.append(row)\n        else:\n            self.rows.insert(index, row)\n        return row\n\n    def remove_row(self, row_id: str) -> bool:\n        row = self._find_row(row_id)\n        if row is None:\n            return False\n        self.rows.remove(row)\n        return True\n\n    def move_row(self, row_id: str, new_index: int) -> bool:\n        row = self._find_row(row_id)\n        if row is None:\n            return False\n        self.rows.remove(row)\n        new_index = max(0, min(new_index, len(self.rows)))\n        self.rows.insert(new_index, row)\n        return True\n\n    def get_cell(self, row_id: str, column_id: str) -> Any:\n        row = self._find_row(row_id)\n        if row is None:\n            return None\n        return row["cells"].get(column_id)\n\n    def set_cell(self, row_id: str, column_id: str, value: Any) -> bool:\n        row = self._find_row(row_id)\n        column = self._find_column(column_id)\n        if row is None or column is None:\n            return False\n        row["cells"][column_id] = _normalize_value_for_column(column, value)\n        return True\n'
_SOURCES['blocks.text_block'] = '"""\nBloc Texte.\n\nPremier type de bloc concret. Sert de base au reste du projet\n(les titres du PATCH 4 en seront des variantes).\n\nDepuis le PATCH 6, le contenu est aussi conservé au format HTML\nafin de préserver la mise en forme (gras, italique, listes, etc.).\n"""\nfrom __future__ import annotations\n\nimport uuid\n\nfrom core.block import Block\n\nTEXT_BLOCK_TYPE = "text"\n\n\nclass TextBlock(Block):\n    """Bloc de texte libre.\n\n    Attributes (dans data):\n        content: texte brut (sans mise en forme), utile pour la\n            recherche (PATCH 28) et comme donnée de secours.\n        html: représentation HTML complète du contenu, avec mise\n            en forme (PATCH 6).\n    """\n\n    def __init__(self, content: str = "", html: str = "", id: str | None = None) -> None:\n        super().__init__(\n            type=TEXT_BLOCK_TYPE,\n            data={"content": content, "html": html},\n            id=id or str(uuid.uuid4()),\n        )\n\n    @property\n    def content(self) -> str:\n        return self.data.get("content", "")\n\n    @content.setter\n    def content(self, value: str) -> None:\n        self.data["content"] = value\n\n    @property\n    def html(self) -> str:\n        return self.data.get("html", "")\n\n    @html.setter\n    def html(self, value: str) -> None:\n        self.data["html"] = value\n'
_SOURCES['core'] = ''
_PACKAGES.add('core')
_SOURCES['core.block'] = '"""\nBloc de base du document.\n\nUn bloc représente une unité de contenu (texte, titre, image, etc.).\nCette classe sera spécialisée par les patches suivants\n(PATCH 3 : bloc texte, PATCH 4 : titres, etc.).\n"""\nfrom __future__ import annotations\n\nimport uuid\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\n\n@dataclass\nclass Block:\n    """Représente un bloc générique dans le document.\n\n    Attributes:\n        type: Type du bloc (ex: "text", "heading1", ...).\n        data: Données propres au bloc (contenu, options, etc.).\n        id: Identifiant unique du bloc (UUID en chaîne).\n    """\n    type: str\n    data: dict[str, Any] = field(default_factory=dict)\n    id: str = field(default_factory=lambda: str(uuid.uuid4()))\n\n    def to_dict(self) -> dict[str, Any]:\n        """Sérialise le bloc en dictionnaire (pour sauvegarde JSON)."""\n        return {"id": self.id, "type": self.type, "data": self.data}\n\n    @classmethod\n    def from_dict(cls, raw: dict[str, Any]) -> "Block":\n        """Reconstruit un bloc à partir d\'un dictionnaire."""\n        return cls(type=raw["type"], data=raw.get("data", {}), id=raw["id"])\n'
_SOURCES['core.block_icons'] = '"""\nIcône représentative d\'un bloc (PATCH 34).\n\nFonction pure (indépendante de Qt) : associe à chaque type de bloc un\nsymbole Unicode, affiché à gauche de chaque bloc dans le document\n(voir BlockContainer). Centralisé ici pour rester la seule source de\nvérité, réutilisable aussi bien par l\'UI que par d\'éventuels exports\n(PATCH 36-38).\n"""\nfrom __future__ import annotations\n\nfrom blocks.bar_chart_block import BarChartBlock\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.dependency_gantt_block import DependencyGanttBlock\nfrom blocks.formula_block import FormulaBlock\nfrom blocks.gantt_block import GanttBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.line_chart_block import LineChartBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.list_block import ListBlock\nfrom blocks.people_list_block import PeopleListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import TableBlock\nfrom blocks.text_block import TextBlock\n\n_DEFAULT_ICON = "▫"\n\n# Associe chaque type concret de bloc à un symbole représentatif.\n# Utilise des tuples (type, symbole) plutôt qu\'un dict indexé par\n# classe pour préserver un ordre de vérification déterministe avec\n# `isinstance` (utile car HeadingBlock hérite indirectement du même\n# module que TextBlock sans en être une sous-classe : pas de risque\n# de faux positif ici, mais garde la même logique que block_preview).\n_ICON_RULES: list[tuple[type, str]] = [\n    (HeadingBlock, "H"),\n    (TextBlock, "¶"),\n    (ChecklistBlock, "☑"),\n    (LinkedChecklistBlock, "⇄"),\n    (PeopleListBlock, "👥"),\n    (ListBlock, "•"),\n    (TableBlock, "▦"),\n    (SimpleTableBlock, "▤"),\n    (GanttBlock, "📊"),\n    (DependencyGanttBlock, "📈"),\n    (LineChartBlock, "📉"),\n    (BarChartBlock, "📶"),\n    (FormulaBlock, "Σ"),\n    (ImageBlock, "🖼"),\n    (QuoteBlock, "❝"),\n    (CodeBlock, "</>"),\n    (SeparatorBlock, "―"),\n]\n\n\ndef icon_for_block(block) -> str:\n    """Symbole représentatif du type de `block` (ou une icône générique\n    par défaut si le type n\'est pas reconnu)."""\n    for block_type, icon in _ICON_RULES:\n        if isinstance(block, block_type):\n            return icon\n    return _DEFAULT_ICON\n'
_SOURCES['core.block_preview'] = '"""\nAperçu textuel d\'un bloc (PATCH 30).\n\nFonction pure (indépendante de Qt) utilisée par le sélecteur de blocs\ndes liens internes : donne un court texte représentatif du contenu\nd\'un bloc, quel que soit son type.\n"""\nfrom __future__ import annotations\n\nfrom blocks.bar_chart_block import BarChartBlock\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.dependency_gantt_block import DependencyGanttBlock\nfrom blocks.formula_block import FormulaBlock\nfrom blocks.gantt_block import GanttBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.line_chart_block import LineChartBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.list_block import ListBlock\nfrom blocks.people_list_block import PeopleListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import TableBlock\nfrom blocks.text_block import TextBlock\n\n_MAX_PREVIEW_LENGTH = 60\n\n\ndef _truncate(text: str) -> str:\n    text = " ".join(text.split())  # aplatit les retours à la ligne\n    if len(text) <= _MAX_PREVIEW_LENGTH:\n        return text\n    return text[:_MAX_PREVIEW_LENGTH].rstrip() + "…"\n\n\ndef preview_for_block(block) -> str:\n    """Court texte représentatif du contenu d\'un bloc, pour l\'afficher\n    dans une liste (sélecteur de lien interne, résultats divers, ...)."""\n    if isinstance(block, (TextBlock, HeadingBlock, QuoteBlock, CodeBlock)):\n        return _truncate(block.content) or "(vide)"\n\n    if isinstance(block, ChecklistBlock):\n        if block.items:\n            return _truncate(block.items[0].get("text", "")) or "(checklist)"\n        return "(checklist vide)"\n\n    if isinstance(block, LinkedChecklistBlock):\n        return f"(checklists liées, {len(block.todo_items())} à faire / {len(block.done_items())} faites)"\n\n    if isinstance(block, PeopleListBlock):\n        return "(effectif)"\n\n    if isinstance(block, ListBlock):\n        if block.items:\n            return _truncate(block.items[0].get("text", "")) or "(liste)"\n        return "(liste vide)"\n\n    if isinstance(block, TableBlock):\n        return f"(tableau, {len(block.columns)} colonne{\'s\' if len(block.columns) != 1 else \'\'})"\n\n    if isinstance(block, SimpleTableBlock):\n        return f"(tableau simple, {block.row_count}×{block.column_count})"\n\n    if isinstance(block, ImageBlock):\n        return "(image)"\n\n    if isinstance(block, GanttBlock):\n        return "(diagramme de Gantt)"\n\n    if isinstance(block, DependencyGanttBlock):\n        return "(Gantt calculé par dépendances)"\n\n    if isinstance(block, LineChartBlock):\n        return f"(graphique en courbes, {len(block.series)} série(s))"\n\n    if isinstance(block, BarChartBlock):\n        return f"(graphique en bâtonnets, {len(block.bars)} barre(s))"\n\n    if isinstance(block, FormulaBlock):\n        return f"({block.label.strip() or \'résultat calculé\'})"\n\n    if isinstance(block, SeparatorBlock):\n        return "(séparateur)"\n\n    return "(bloc)"\n'
_SOURCES['core.document'] = '"""\nGestionnaire de document.\n\nLe Document est l\'unique source de vérité : il contient la liste\nordonnée des blocs et expose les opérations de base (ajout,\nsuppression, déplacement, recherche par ID).\n"""\nfrom __future__ import annotations\n\nfrom typing import Any, Optional\n\nfrom core.block import Block\nfrom core.people_registry import PERSON_COLOR_PALETTE, PeopleRegistry\n\nDOCUMENT_FORMAT_VERSION = 1\n\n# Ré-exporté pour compatibilité (le registre partagé, core.people_registry,\n# est désormais la source de vérité de la palette — PATCH 82).\n__all__ = ["Document", "DOCUMENT_FORMAT_VERSION", "PERSON_COLOR_PALETTE"]\n\n\nclass Document:\n    """Représente un document composé d\'une liste ordonnée de blocs.\n\n    Depuis le PATCH 82, le nom et la couleur des personnes ne sont\n    plus stockés dans le document lui-même mais dans un registre\n    système partagé, réutilisable d\'un projet à l\'autre (voir\n    `core.people_registry.PeopleRegistry`). Le document ne conserve que\n    la liste des identifiants de personnes qu\'il référence : c\'est ce\n    qui permet à une même personne de garder le même nom et la même\n    couleur dans tous les projets, et à un projet de "détacher" une\n    personne sans la supprimer ailleurs.\n    """\n\n    def __init__(self, people_registry: PeopleRegistry | None = None) -> None:\n        self._blocks: list[Block] = []\n        self._people_registry = people_registry or PeopleRegistry()\n        self._person_ids: list[str] = []\n        self._favorite_ids: list[str] = []\n\n    @property\n    def people_registry(self) -> PeopleRegistry:\n        """Le registre système partagé utilisé par ce document."""\n        return self._people_registry\n\n    @property\n    def blocks(self) -> list[Block]:\n        """Retourne la liste ordonnée des blocs (copie superficielle)."""\n        return list(self._blocks)\n\n    def add_block(self, block: Block, index: Optional[int] = None) -> None:\n        """Ajoute un bloc au document.\n\n        Args:\n            block: Le bloc à ajouter.\n            index: Position d\'insertion. Si None, ajoute à la fin.\n        """\n        if index is None:\n            self._blocks.append(block)\n        else:\n            self._blocks.insert(index, block)\n\n    def remove_block(self, block_id: str) -> bool:\n        """Supprime un bloc par son ID.\n\n        Returns:\n            True si un bloc a été supprimé, False s\'il n\'a pas été trouvé.\n        """\n        block = self.find_block(block_id)\n        if block is None:\n            return False\n        self._blocks.remove(block)\n        if block_id in self._favorite_ids:\n            self._favorite_ids.remove(block_id)\n        return True\n\n    def move_block(self, block_id: str, new_index: int) -> bool:\n        """Déplace un bloc vers une nouvelle position.\n\n        Returns:\n            True si le déplacement a réussi, False si le bloc est introuvable.\n        """\n        block = self.find_block(block_id)\n        if block is None:\n            return False\n        self._blocks.remove(block)\n        new_index = max(0, min(new_index, len(self._blocks)))\n        self._blocks.insert(new_index, block)\n        return True\n\n    def find_block(self, block_id: str) -> Optional[Block]:\n        """Recherche un bloc par son ID.\n\n        Returns:\n            Le bloc correspondant, ou None si aucun bloc ne correspond.\n        """\n        for block in self._blocks:\n            if block.id == block_id:\n                return block\n        return None\n\n    def __len__(self) -> int:\n        return len(self._blocks)\n\n    # -- Registre des personnes (PATCH 16, revu PATCH 82) -----------------\n    #\n    # Le nom et la couleur vivent dans le registre système partagé\n    # (self._people_registry) ; le document ne garde que les ids des\n    # personnes qui font partie de CE projet (self._person_ids), pour\n    # savoir lesquelles afficher dans le bloc "Effectif" et proposer\n    # dans les colonnes "Personne" des tableaux.\n\n    @property\n    def people(self) -> list[dict[str, Any]]:\n        """Personnes de ce projet (nom/couleur résolus depuis le\n        registre système partagé). Une personne dont l\'id n\'existerait\n        plus dans le registre (supprimée ailleurs) est simplement\n        omise, plutôt que de faire planter l\'affichage."""\n        people = []\n        for person_id in self._person_ids:\n            person = self._people_registry.find_person(person_id)\n            if person is not None:\n                people.append(person)\n        return people\n\n    def find_person(self, person_id: str) -> Optional[dict[str, Any]]:\n        """Une personne, mais seulement si elle fait partie de ce projet."""\n        if person_id not in self._person_ids:\n            return None\n        return self._people_registry.find_person(person_id)\n\n    def add_person(self, name: str, color: str | None = None) -> dict[str, Any]:\n        """Ajoute (ou réutilise, si elle existe déjà sous ce nom dans le\n        registre partagé) une personne, et l\'associe à ce projet."""\n        person = self._people_registry.add_person(name, color)\n        if person["id"] not in self._person_ids:\n            self._person_ids.append(person["id"])\n        return person\n\n    def link_person(self, person_id: str) -> bool:\n        """Associe à ce projet une personne déjà connue du registre\n        partagé (typiquement créée depuis un autre projet). Retourne\n        False si cet id est inconnu du registre."""\n        if self._people_registry.find_person(person_id) is None:\n            return False\n        if person_id not in self._person_ids:\n            self._person_ids.append(person_id)\n        return True\n\n    def rename_person(self, person_id: str, name: str) -> bool:\n        if person_id not in self._person_ids:\n            return False\n        return self._people_registry.rename_person(person_id, name)\n\n    def set_person_color(self, person_id: str, color: str) -> bool:\n        if person_id not in self._person_ids:\n            return False\n        return self._people_registry.set_person_color(person_id, color)\n\n    def remove_person(self, person_id: str) -> bool:\n        """Détache une personne de CE projet et purge ses références\n        dans les colonnes "Personne" des blocs Tableau du document.\n\n        Contrairement à l\'ancien comportement (PATCH 16), ceci ne\n        supprime PAS la personne du registre partagé : elle reste\n        disponible pour les autres projets. Pour la supprimer\n        définitivement partout, voir `self.people_registry.remove_person`.\n        """\n        if person_id not in self._person_ids:\n            return False\n        self._person_ids.remove(person_id)\n\n        # Import local pour éviter un import circulaire (blocks -> core).\n        from blocks.table_block import COLUMN_TYPE_PERSON\n        from blocks.table_block import TableBlock\n\n        for block in self._blocks:\n            if not isinstance(block, TableBlock):\n                continue\n            person_columns = [c for c in block.columns if c["type"] == COLUMN_TYPE_PERSON]\n            for column in person_columns:\n                for row in block.rows:\n                    current = row["cells"].get(column["id"]) or []\n                    if person_id in current:\n                        block.set_cell(row["id"], column["id"], [p for p in current if p != person_id])\n        return True\n\n    # -- Favoris (PATCH 31) ------------------------------------------------\n\n    @property\n    def favorite_ids(self) -> list[str]:\n        """Ids des blocs favoris, dans leur ordre d\'ajout aux favoris."""\n        return list(self._favorite_ids)\n\n    def is_favorite(self, block_id: str) -> bool:\n        return block_id in self._favorite_ids\n\n    def add_favorite(self, block_id: str) -> bool:\n        """Marque un bloc comme favori. False si le bloc n\'existe pas\n        ou s\'il est déjà favori."""\n        if self.find_block(block_id) is None or block_id in self._favorite_ids:\n            return False\n        self._favorite_ids.append(block_id)\n        return True\n\n    def remove_favorite(self, block_id: str) -> bool:\n        if block_id not in self._favorite_ids:\n            return False\n        self._favorite_ids.remove(block_id)\n        return True\n\n    def toggle_favorite(self, block_id: str) -> Optional[bool]:\n        """Bascule l\'état favori d\'un bloc. Retourne le nouvel état\n        (True si désormais favori), ou None si le bloc n\'existe pas."""\n        if self.find_block(block_id) is None:\n            return None\n        if self.is_favorite(block_id):\n            self.remove_favorite(block_id)\n            return False\n        self.add_favorite(block_id)\n        return True\n\n    def favorite_blocks(self) -> list[Block]:\n        """Blocs favoris, dans l\'ordre du document (pas l\'ordre d\'ajout\n        aux favoris) — plus utile pour un panneau de navigation."""\n        favorites = set(self._favorite_ids)\n        return [block for block in self._blocks if block.id in favorites]\n\n    # -- Sauvegarde / chargement JSON (PATCH 8) ---------------------------\n\n    def to_dict(self) -> dict[str, Any]:\n        """Sérialise le document entier (format de sauvegarde JSON).\n\n        Depuis le PATCH 82, seuls les identifiants des personnes de ce\n        projet sont sauvegardés ("person_ids") : leur nom et leur\n        couleur vivent dans le registre système partagé, pas dans ce\n        fichier (voir `core.people_registry`).\n        """\n        return {\n            "version": DOCUMENT_FORMAT_VERSION,\n            "blocks": [block.to_dict() for block in self._blocks],\n            "person_ids": list(self._person_ids),\n            "favorite_ids": list(self._favorite_ids),\n        }\n\n    @classmethod\n    def from_dict(cls, raw: dict[str, Any], people_registry: PeopleRegistry | None = None) -> "Document":\n        """Reconstruit un document complet à partir d\'un dictionnaire JSON.\n\n        Toutes les données de chaque bloc (id, type, contenu complet)\n        sont restaurées à l\'identique (PATCH 9).\n\n        Args:\n            raw: Le document sérialisé (voir `to_dict`).\n            people_registry: Registre système à utiliser. Par défaut,\n                celui de l\'utilisateur courant (voir\n                `core.people_registry.default_registry_path`).\n\n        Raises:\n            ValueError: si le fichier a été sauvegardé par une version\n                plus récente du format que celle supportée ici.\n        """\n        file_version = raw.get("version", DOCUMENT_FORMAT_VERSION)\n        if file_version > DOCUMENT_FORMAT_VERSION:\n            raise ValueError(\n                f"Ce fichier a été créé avec une version plus récente du "\n                f"format ({file_version}) que celle supportée ({DOCUMENT_FORMAT_VERSION})."\n            )\n\n        # Import local pour éviter un import circulaire (blocks -> core.block).\n        from blocks.registry import block_from_dict\n\n        if "blocks" not in raw:\n            raise ValueError("Fichier invalide : clé \'blocks\' manquante.")\n\n        document = cls(people_registry=people_registry)\n        for raw_block in raw["blocks"]:\n            document.add_block(block_from_dict(raw_block))\n\n        # PATCH 82 — Rétrocompatibilité : les fichiers créés avant ce\n        # patch embarquent encore une liste "people" complète (id, nom,\n        # couleur). On la migre dans le registre partagé, en évitant\n        # les doublons si une personne du même nom y existe déjà.\n        for raw_person in raw.get("people", []):\n            name = raw_person.get("name", "")\n            existing = document._people_registry.find_person(raw_person.get("id", ""))\n            if existing is not None:\n                person_id = existing["id"]\n            else:\n                migrated = document._people_registry.add_person(\n                    name, raw_person.get("color")\n                )\n                person_id = migrated["id"]\n            if person_id not in document._person_ids:\n                document._person_ids.append(person_id)\n\n        # Format courant : uniquement des ids, résolus dans le registre.\n        for person_id in raw.get("person_ids", []):\n            if document._people_registry.find_person(person_id) is not None:\n                if person_id not in document._person_ids:\n                    document._person_ids.append(person_id)\n\n        # Ne conserve que les ids référençant un bloc effectivement chargé\n        # (robustesse face à un fichier corrompu ou édité à la main).\n        existing_ids = {block.id for block in document._blocks}\n        document._favorite_ids = [\n            fid for fid in raw.get("favorite_ids", []) if fid in existing_ids\n        ]\n        return document\n'
_SOURCES['core.document_html_export'] = '"""\nRendu HTML du document (PATCH 36 — support de l\'export PDF).\n\nFonction pure `document_to_html(document)` : traduit chaque bloc en un\nfragment HTML autonome (indépendant de Qt, testable sans QApplication).\n`ui/export_pdf.py` réutilise ce HTML avec QTextDocument + QPrinter\npour produire le fichier PDF final.\n"""\nfrom __future__ import annotations\n\nimport html as html_module\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.formula_block import FormulaBlock, compute_formula_result, format_formula_text\nfrom blocks.bar_chart_block import BarChartBlock, sync_bars_from_gantt\nfrom blocks.dependency_gantt_block import DependencyGanttBlock, compute_schedule\nfrom blocks.line_chart_block import LineChartBlock, compute_line_series\nfrom blocks.gantt_block import GanttBlock, compute_gantt_rows\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.list_block import LIST_TYPE_NUMBERED, ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import COLUMN_TYPE_BOOLEAN, COLUMN_TYPE_CHECKLIST, COLUMN_TYPE_DATE, COLUMN_TYPE_DURATION, COLUMN_TYPE_MULTI_SELECT, COLUMN_TYPE_PERSON, COLUMN_TYPE_TEXT, TableBlock\nfrom blocks.text_block import TextBlock\nfrom core.duration import format_duration\n\n\ndef _esc(text) -> str:\n    if text is None:\n        text = ""\n    elif not isinstance(text, str):\n        text = str(text)\n    return html_module.escape(text)\n\n\ndef _format_day(value: float) -> str:\n    """Formate un décalage en jours (float) en texte lisible, ex.\n    3.0 -> "Jour 3", 2.5 -> "Jour 2.5" (PATCH 62 — correctif export PDF)."""\n    rounded = round(value, 2)\n    if rounded == int(rounded):\n        return f"Jour {int(rounded)}"\n    return f"Jour {rounded:g}"\n\n\ndef _render_table_cell(document, column: dict, value) -> str:\n    col_type = column["type"]\n    if value is None:\n        return ""\n    if col_type == COLUMN_TYPE_BOOLEAN:\n        return "☑" if value else "☐"\n    if col_type == COLUMN_TYPE_DURATION:\n        return _esc(format_duration(value))\n    if col_type == COLUMN_TYPE_DATE and isinstance(value, dict):\n        return _esc(f"{value.get(\'start\', \'\')} → {value.get(\'end\', \'\')}")\n    if col_type == COLUMN_TYPE_PERSON:\n        names = [(document.find_person(pid) or {}).get("name", "?") for pid in (value or [])]\n        return _esc(", ".join(names))\n    if col_type == COLUMN_TYPE_MULTI_SELECT:\n        return _esc(", ".join(value or []))\n    if col_type == COLUMN_TYPE_CHECKLIST:\n        done = sum(1 for item in (value or []) if item.get("checked"))\n        return _esc(f"{done}/{len(value or [])}")\n    return _esc(str(value))\n\n\ndef _compute_column_spans(block: TableBlock, column: dict) -> list[int]:\n    """Pour une colonne donnée, calcule le rowspan à appliquer à chaque\n    ligne (par index) : N si la ligne démarre une fusion de N lignes,\n    1 si elle n\'est pas fusionnée, 0 si elle est absorbée par la fusion\n    d\'une ligne précédente (ne doit alors pas être rendue). Reproduit\n    exactement la logique de `TableBlockWidget._apply_merged_cells`\n    (PATCH 63 — correctif export PDF) : fusion manuelle (clic droit)\n    en priorité, sinon fusion automatique des valeurs identiques\n    consécutives d\'une colonne "Texte".\n    """\n    rows = block.rows\n    spans = [1] * len(rows)\n    row_index_by_id = {row["id"]: i for i, row in enumerate(rows)}\n\n    manual_groups = block.manual_merge_groups(column["id"])\n    if manual_groups:\n        for group in manual_groups:\n            indices = sorted(row_index_by_id[rid] for rid in group if rid in row_index_by_id)\n            if len(indices) < 2:\n                continue\n            if indices == list(range(indices[0], indices[0] + len(indices))):\n                spans[indices[0]] = len(indices)\n                for i in indices[1:]:\n                    spans[i] = 0\n        return spans\n\n    if column["type"] != COLUMN_TYPE_TEXT:\n        return spans\n\n    run_start = 0\n    while run_start < len(rows):\n        value = rows[run_start]["cells"].get(column["id"])\n        run_end = run_start + 1\n        while run_end < len(rows) and rows[run_end]["cells"].get(column["id"]) == value and value:\n            run_end += 1\n        run_length = run_end - run_start\n        if run_length > 1:\n            spans[run_start] = run_length\n            for i in range(run_start + 1, run_end):\n                spans[i] = 0\n        run_start = run_end\n    return spans\n\n\ndef _render_table_block(document, block: TableBlock) -> str:\n    header = "".join(f"<th>{_esc(c[\'name\'])}</th>" for c in block.columns)\n    column_spans = [_compute_column_spans(block, column) for column in block.columns]\n    rows_html = ""\n    for row_index, row in enumerate(block.rows):\n        cells = ""\n        for col_index, column in enumerate(block.columns):\n            span = column_spans[col_index][row_index]\n            if span == 0:\n                continue  # absorbée par la fusion d\'une ligne précédente\n            rowspan_attr = f\' rowspan="{span}"\' if span > 1 else ""\n            value_html = _render_table_cell(document, column, row["cells"].get(column["id"]))\n            cells += f"<td{rowspan_attr}>{value_html}</td>"\n        rows_html += f"<tr>{cells}</tr>"\n    return f\'<table border="1" cellspacing="0" cellpadding="4"><tr>{header}</tr>{rows_html}</table>\'\n\n\ndef _render_simple_table_block(block: SimpleTableBlock) -> str:\n    rows_html = "".join(\n        "<tr>" + "".join(f"<td>{_esc(cell)}</td>" for cell in row) + "</tr>" for row in block.rows\n    )\n    return f\'<table border="1" cellspacing="0" cellpadding="4">{rows_html}</table>\'\n\n\ndef _render_gantt_block(document, block: GanttBlock) -> str:\n    rows = compute_gantt_rows(document, block)\n    if not rows:\n        return "<p><i>(Gantt vide ou non configuré)</i></p>"\n    rows_html = "".join(\n        f"<tr><td>{_esc(r[\'label\'])}</td><td>{_esc(r[\'start\'] or \'\')}</td>"\n        f"<td>{_esc(r[\'end\'] or \'\')}</td></tr>"\n        for r in rows\n    )\n    return (\n        \'<table border="1" cellspacing="0" cellpadding="4">\'\n        "<tr><th>Tâche</th><th>Début</th><th>Fin</th></tr>" + rows_html + "</table>"\n    )\n\n\ndef _render_dependency_gantt_block(document, block: DependencyGanttBlock) -> str:\n    schedule = compute_schedule(document, block)\n    if not schedule:\n        return "<p><i>(Gantt par dépendances vide ou non configuré)</i></p>"\n    rows_html = "".join(\n        f"<tr><td>{_esc(t[\'label\'])}</td><td>{_esc(\', \'.join(t[\'person_names\']))}</td>"\n        f"<td>{_esc(_format_day(t[\'start\']))}</td><td>{_esc(_format_day(t[\'end\']))}</td>"\n        f"<td>{_esc(_format_day(t[\'resolution\']))}</td></tr>"\n        for t in schedule\n    )\n    return (\n        \'<table border="1" cellspacing="0" cellpadding="4">\'\n        "<tr><th>Sous-tâche</th><th>Personnes</th><th>Début</th><th>Fin</th><th>Résolution</th></tr>"\n        + rows_html\n        + "</table>"\n    )\n\n\ndef _render_line_chart_block(document, block: LineChartBlock) -> str:\n    series = compute_line_series(document, block)\n    title = block.title or "(sans titre)"\n    axes = f" — {_esc(block.x_axis_label)} / {_esc(block.y_axis_label)}" if (block.x_axis_label or block.y_axis_label) else ""\n    if not series:\n        return f"<p><b>{_esc(title)}</b>{axes} (aucune série)</p>"\n    rows_html = "".join(\n        f"<tr><td>{_esc(s[\'name\'])}</td><td>{_esc(s[\'slope\'])}</td></tr>" for s in series\n    )\n    return (\n        f"<p><b>{_esc(title)}</b>{axes}</p>"\n        \'<table border="1" cellspacing="0" cellpadding="4">\'\n        "<tr><th>Droite</th><th>Pente</th></tr>" + rows_html + "</table>"\n    )\n\n\ndef _render_bar_chart_block(document, block: BarChartBlock, chart_renderer=None) -> str:\n    # PATCH 78 — si un `chart_renderer` (callback fourni par l\'export PDF,\n    # voir ui/export_pdf.py) sait produire une image du graphique tel\n    # qu\'affiché dans l\'app, on l\'utilise à la place du tableau de\n    # données ci-dessous (conservé comme repli, ex. export HTML pur\n    # sans Qt disponible, ou graphique vide).\n    if chart_renderer is not None:\n        image_html = chart_renderer(document, block)\n        if image_html is not None:\n            return image_html\n    bars = sync_bars_from_gantt(document, block)\n    if not bars:\n        return f"<p><b>{_esc(block.title)}</b> (aucune barre)</p>"\n    rows_html = "".join(\n        f"<tr><td>{_esc(b[\'label\'])}</td><td>{_esc(b[\'value\'])}</td>"\n        f"<td>{_esc(b[\'actual\']) if b[\'actual\'] is not None else \'—\'}</td></tr>"\n        for b in bars\n    )\n    return (\n        f"<p><b>{_esc(block.title)}</b> ({_esc(block.y_axis_label)})</p>"\n        \'<table border="1" cellspacing="0" cellpadding="4">\'\n        "<tr><th>Catégorie</th><th>Prévu</th><th>Réel</th></tr>" + rows_html + "</table>"\n    )\n\n\ndef _render_checklist_block(block: ChecklistBlock) -> str:\n    items = "".join(\n        f"<li>{\'☑\' if item.get(\'checked\') else \'☐\'} {_esc(item.get(\'text\', \'\'))}</li>"\n        for item in block.items\n    )\n    return f"<ul>{items}</ul>"\n\n\ndef _render_linked_checklist_block(block: LinkedChecklistBlock) -> str:\n    todo = "".join(f"<li>☐ {_esc(item.get(\'text\', \'\'))}</li>" for item in block.todo_items())\n    done = "".join(f"<li>☑ {_esc(item.get(\'text\', \'\'))}</li>" for item in block.done_items())\n    return (\n        \'<table border="0" cellspacing="0" cellpadding="4"><tr>\'\n        f\'<td valign="top"><b>À faire</b><ul>{todo}</ul></td>\'\n        f\'<td valign="top"><b>Faites</b><ul>{done}</ul></td>\'\n        "</tr></table>"\n    )\n\n\ndef _render_list_block(block: ListBlock) -> str:\n    tag = "ol" if block.list_type == LIST_TYPE_NUMBERED else "ul"\n    items = "".join(f"<li>{_esc(item.get(\'text\', \'\'))}</li>" for item in block.items)\n    return f"<{tag}>{items}</{tag}>"\n\n\ndef _render_block(document, block, chart_renderer=None) -> str:\n    if isinstance(block, HeadingBlock):\n        level = block.data.get("level", 1)\n        return f"<h{level}>{_esc(block.content)}</h{level}>"\n    if isinstance(block, TextBlock):\n        return block.html or f"<p>{_esc(block.content)}</p>"\n    if isinstance(block, ChecklistBlock):\n        return _render_checklist_block(block)\n    if isinstance(block, LinkedChecklistBlock):\n        return _render_linked_checklist_block(block)\n    if isinstance(block, ListBlock):\n        return _render_list_block(block)\n    if isinstance(block, TableBlock):\n        return _render_table_block(document, block)\n    if isinstance(block, SimpleTableBlock):\n        return _render_simple_table_block(block)\n    if isinstance(block, GanttBlock):\n        return _render_gantt_block(document, block)\n    if isinstance(block, DependencyGanttBlock):\n        return _render_dependency_gantt_block(document, block)\n    if isinstance(block, FormulaBlock):\n        return f"<p>{_esc(format_formula_text(block, compute_formula_result(document, block)))}</p>"\n    if isinstance(block, LineChartBlock):\n        return _render_line_chart_block(document, block)\n    if isinstance(block, BarChartBlock):\n        return _render_bar_chart_block(document, block, chart_renderer)\n    if isinstance(block, ImageBlock):\n        if not block.data.get("image_base64"):\n            return "<p><i>(image vide)</i></p>"\n        fmt = block.data.get("format", "png")\n        width_attr = f\' width="{block.data["width"]}"\' if block.data.get("width") else ""\n        return f\'<img src="data:image/{fmt};base64,{block.data["image_base64"]}"{width_attr} />\'\n    if isinstance(block, QuoteBlock):\n        return f"<blockquote><i>{_esc(block.content)}</i></blockquote>"\n    if isinstance(block, CodeBlock):\n        return f"<pre><code>{_esc(block.content)}</code></pre>"\n    if isinstance(block, SeparatorBlock):\n        return "<hr/>"\n    return ""\n\n\ndef document_to_html(document, chart_renderer=None) -> str:\n    """Convertit tout le document en un unique fragment HTML, dans\n    l\'ordre des blocs. Chaque bloc est rendu de façon indépendante ;\n    un bloc au rendu inconnu (nouveau type non géré ici) est ignoré\n    plutôt que de faire échouer tout l\'export.\n\n    PATCH 78 — `chart_renderer(document, block) -> str | None` est un\n    callback optionnel (fourni par `ui/export_pdf.py`, qui a accès à\n    Qt) capable de rendre un bloc graphique en véritable image\n    (identique à l\'app) plutôt qu\'en tableau de données. Ce module\n    reste volontairement sans dépendance Qt : sans callback (export\n    HTML, tests), le repli en tableau est utilisé.\n    """\n    parts = [_render_block(document, block, chart_renderer) for block in document.blocks]\n    return "\\n".join(part for part in parts if part)\n\n\n_PAGE_TEMPLATE = """<!DOCTYPE html>\n<html lang="fr">\n<head>\n<meta charset="utf-8" />\n<title>{title}</title>\n<style>\n  body {{ font-family: -apple-system, "Segoe UI", Arial, sans-serif; max-width: 800px;\n          margin: 40px auto; padding: 0 16px; line-height: 1.5; color: #222; }}\n  h1, h2, h3 {{ margin-top: 28px; margin-bottom: 10px; }}\n  p {{ margin: 8px 0; }}\n  table {{ border-collapse: collapse; width: 100%; margin: 18px 0; }}\n  th, td {{ border: 1px solid #ccc; padding: 6px 10px; text-align: left; vertical-align: top; }}\n  blockquote {{ border-left: 3px solid #999; margin: 12px 0; padding-left: 12px; color: #555; }}\n  pre {{ background: #f5f5f5; border: 1px solid #ddd; padding: 10px; overflow-x: auto; margin: 12px 0; }}\n  img {{ max-width: 100%; margin: 18px 0; }}\n  hr {{ border: none; border-top: 1px solid #ccc; margin: 20px 0; }}\n</style>\n</head>\n<body>\n{body}\n</body>\n</html>\n"""\n\n\ndef document_to_full_html(document, title: str = "Document", chart_renderer=None) -> str:\n    """PATCH 38 — Document HTML autonome et lisible dans un navigateur\n    (doctype, head avec charset + CSS minimal, body). Réutilise\n    `document_to_html` pour le contenu, sans dupliquer la logique de\n    rendu par bloc — un seul moteur pour les exports PDF et HTML.\n    PATCH 78 — voir `document_to_html` pour `chart_renderer`."""\n    return _PAGE_TEMPLATE.format(title=_esc(title), body=document_to_html(document, chart_renderer))'
_SOURCES['core.document_html_import'] = '"""\nImport HTML (PATCH 40).\n\nFonction pure `html_to_document(html_text)` : lit un document HTML\n(idéalement produit par `document_to_full_html`, PATCH 38, mais\ntolérant à du HTML raisonnablement simple écrit à la main) et\nreconstruit un Document avec les blocs correspondants.\n\nAnalyseur à base d\'expressions régulières (pas de dépendance externe\ntype BeautifulSoup) : suffisant pour une structure de blocs top-level\nnon imbriqués (ce que produit notre propre export), mais ne gère pas\nles imbrications profondes (ex. liste dans une liste) — limitation\ndocumentée, comme pour l\'import Markdown (PATCH 39).\n"""\nfrom __future__ import annotations\n\nimport html as html_module\nimport re\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.list_block import LIST_TYPE_BULLET, LIST_TYPE_NUMBERED, ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.text_block import TextBlock\nfrom core.document import Document\n\n_TAG_RE = re.compile(r"<[^>]+>")\n_LI_RE = re.compile(r"<li[^>]*>(.*?)</li>", re.DOTALL | re.IGNORECASE)\n_ROW_RE = re.compile(r"<tr[^>]*>(.*?)</tr>", re.DOTALL | re.IGNORECASE)\n_CELL_RE = re.compile(r"<t[dh][^>]*>(.*?)</t[dh]>", re.DOTALL | re.IGNORECASE)\n_IMG_SRC_RE = re.compile(r\'src="data:image/([^;]+);base64,([^"]+)"\')\n_IMG_WIDTH_RE = re.compile(r\'width="(\\d+)"\')\n\n_BLOCK_RE = re.compile(\n    r"<(?P<tag>h[1-6]|p|ul|ol|blockquote|pre|table)\\b[^>]*>(?P<inner>.*?)</(?P=tag)>"\n    r"|<hr\\s*/?>"\n    r"|<img\\b[^>]*/?>",\n    re.DOTALL | re.IGNORECASE,\n)\n\n\ndef _strip_tags(fragment: str) -> str:\n    """Retire les balises et décode les entités HTML."""\n    return html_module.unescape(_TAG_RE.sub("", fragment)).strip()\n\n\ndef _extract_body(text: str) -> str:\n    """Ne garde que le contenu de <body>...</body> s\'il existe (retire\n    doctype/head/style), sinon retourne le texte tel quel."""\n    match = re.search(r"<body[^>]*>(.*)</body>", text, re.DOTALL | re.IGNORECASE)\n    return match.group(1) if match else text\n\n\ndef _parse_list_items(inner_html: str) -> list[str]:\n    return [_strip_tags(item) for item in _LI_RE.findall(inner_html)]\n\n\ndef _parse_table_rows(inner_html: str) -> list[list[str]]:\n    rows = []\n    for row_html in _ROW_RE.findall(inner_html):\n        rows.append([_strip_tags(cell) for cell in _CELL_RE.findall(row_html)])\n    return rows\n\n\ndef _list_block_from(tag: str, inner_html: str) -> ListBlock | ChecklistBlock:\n    items = _parse_list_items(inner_html)\n    # Une liste dont TOUS les éléments commencent par ☑/☐ (marqueurs\n    # produits par notre propre export de checklist) redevient une\n    # ChecklistBlock plutôt qu\'une ListBlock générique.\n    if items and all(item.startswith(("☑", "☐")) for item in items):\n        block = ChecklistBlock()\n        for item in items:\n            checked = item.startswith("☑")\n            block.add_item(item[1:].strip(), checked=checked)\n        return block\n\n    list_type = LIST_TYPE_NUMBERED if tag == "ol" else LIST_TYPE_BULLET\n    block = ListBlock(list_type=list_type)\n    for item in items:\n        block.add_item(item)\n    return block\n\n\ndef _image_block_from(tag_html: str) -> ImageBlock | None:\n    src_match = _IMG_SRC_RE.search(tag_html)\n    if not src_match:\n        return None\n    width_match = _IMG_WIDTH_RE.search(tag_html)\n    return ImageBlock(\n        image_base64=src_match.group(2),\n        image_format=src_match.group(1),\n        width=int(width_match.group(1)) if width_match else None,\n    )\n\n\ndef html_to_document(text: str) -> Document:\n    """Reconstruit un Document à partir d\'une chaîne HTML."""\n    document = Document()\n    body = _extract_body(text)\n\n    for match in _BLOCK_RE.finditer(body):\n        whole = match.group(0)\n        tag = match.group("tag")\n\n        if tag is None:\n            if whole.lower().startswith("<hr"):\n                document.add_block(SeparatorBlock())\n            elif whole.lower().startswith("<img"):\n                image = _image_block_from(whole)\n                if image is not None:\n                    document.add_block(image)\n            continue\n\n        inner = match.group("inner")\n        tag = tag.lower()\n\n        if tag.startswith("h") and tag[1:].isdigit():\n            level = min(int(tag[1:]), 3)\n            document.add_block(HeadingBlock(level=level, content=_strip_tags(inner)))\n        elif tag == "p":\n            text_content = _strip_tags(inner)\n            if text_content:\n                block = TextBlock(content=text_content)\n                block.html = f"<p>{inner}</p>"\n                document.add_block(block)\n        elif tag in ("ul", "ol"):\n            document.add_block(_list_block_from(tag, inner))\n        elif tag == "blockquote":\n            document.add_block(QuoteBlock(content=_strip_tags(inner)))\n        elif tag == "pre":\n            code_match = re.search(r"<code[^>]*>(.*?)</code>", inner, re.DOTALL | re.IGNORECASE)\n            code_text = html_module.unescape(code_match.group(1) if code_match else inner)\n            document.add_block(CodeBlock(content=code_text.strip("\\n")))\n        elif tag == "table":\n            rows = _parse_table_rows(inner)\n            if rows:\n                document.add_block(SimpleTableBlock(rows=rows))\n\n    return document\n'
_SOURCES['core.document_markdown_export'] = '"""\nRendu Markdown du document (PATCH 37).\n\nFonction pure `document_to_markdown(document)` : traduit chaque bloc\nen Markdown standard (GitHub-flavored pour les tableaux et cases à\ncocher). Le bloc Texte riche (gras, italique...) est exporté en texte\nbrut : Markdown n\'a pas d\'équivalent direct pour toute la mise en\nforme HTML supportée par TextBlock (PATCH 6) ; l\'export PDF (PATCH 36)\nreste la référence pour une fidélité complète.\n"""\nfrom __future__ import annotations\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.formula_block import FormulaBlock, compute_formula_result, format_formula_text\nfrom blocks.bar_chart_block import BarChartBlock\nfrom blocks.dependency_gantt_block import DependencyGanttBlock, compute_schedule\nfrom blocks.line_chart_block import LineChartBlock, compute_line_series\nfrom blocks.gantt_block import GanttBlock, compute_gantt_rows\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.image_block import ImageBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.list_block import LIST_TYPE_NUMBERED, ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import (\n    COLUMN_TYPE_BOOLEAN,\n    COLUMN_TYPE_CHECKLIST,\n    COLUMN_TYPE_DATE,\n    COLUMN_TYPE_DURATION,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_PERSON,\n    TableBlock,\n)\nfrom blocks.text_block import TextBlock\nfrom core.duration import format_duration\n\n\ndef _md_escape_cell(text: str) -> str:\n    """Échappe le caractère "|" (séparateur de colonnes Markdown)."""\n    return (text or "").replace("|", "\\\\|").replace("\\n", " ")\n\n\ndef _render_table_cell(document, column: dict, value) -> str:\n    col_type = column["type"]\n    if value is None:\n        return ""\n    if col_type == COLUMN_TYPE_BOOLEAN:\n        return "☑" if value else "☐"\n    if col_type == COLUMN_TYPE_DURATION:\n        return format_duration(value)\n    if col_type == COLUMN_TYPE_DATE and isinstance(value, dict):\n        return f"{value.get(\'start\', \'\')} → {value.get(\'end\', \'\')}"\n    if col_type == COLUMN_TYPE_PERSON:\n        names = [(document.find_person(pid) or {}).get("name", "?") for pid in (value or [])]\n        return ", ".join(names)\n    if col_type == COLUMN_TYPE_MULTI_SELECT:\n        return ", ".join(value or [])\n    if col_type == COLUMN_TYPE_CHECKLIST:\n        done = sum(1 for item in (value or []) if item.get("checked"))\n        return f"{done}/{len(value or [])}"\n    return str(value)\n\n\ndef _markdown_table(headers: list[str], rows: list[list[str]]) -> str:\n    header_line = "| " + " | ".join(_md_escape_cell(h) for h in headers) + " |"\n    separator_line = "| " + " | ".join("---" for _ in headers) + " |"\n    row_lines = [\n        "| " + " | ".join(_md_escape_cell(cell) for cell in row) + " |" for row in rows\n    ]\n    return "\\n".join([header_line, separator_line, *row_lines])\n\n\ndef _render_table_block(document, block: TableBlock) -> str:\n    headers = [c["name"] or "" for c in block.columns]\n    rows = [\n        [_render_table_cell(document, column, row["cells"].get(column["id"])) for column in block.columns]\n        for row in block.rows\n    ]\n    return _markdown_table(headers, rows)\n\n\ndef _render_simple_table_block(block: SimpleTableBlock) -> str:\n    if not block.rows:\n        return ""\n    return _markdown_table(block.rows[0], block.rows[1:])\n\n\ndef _render_gantt_block(document, block: GanttBlock) -> str:\n    rows = compute_gantt_rows(document, block)\n    if not rows:\n        return "*(Gantt vide ou non configuré)*"\n    return _markdown_table(\n        ["Tâche", "Début", "Fin"],\n        [[r["label"], r["start"] or "", r["end"] or ""] for r in rows],\n    )\n\n\ndef _render_dependency_gantt_block(document, block: DependencyGanttBlock) -> str:\n    schedule = compute_schedule(document, block)\n    if not schedule:\n        return "*(Gantt par dépendances vide ou non configuré)*"\n    return _markdown_table(\n        ["Sous-tâche", "Personnes", "Début", "Fin", "Résolution"],\n        [\n            [t["label"], ", ".join(t["person_names"]), str(t["start"]), str(t["end"]), str(t["resolution"])]\n            for t in schedule\n        ],\n    )\n\n\ndef _render_line_chart_block(document, block: LineChartBlock) -> str:\n    series = compute_line_series(document, block)\n    title = block.title or "(sans titre)"\n    axes = f" — {block.x_axis_label} / {block.y_axis_label}" if (block.x_axis_label or block.y_axis_label) else ""\n    if not series:\n        return f"**{title}**{axes} *(aucune série)*"\n    table = _markdown_table(["Droite", "Pente"], [[s["name"], str(s["slope"])] for s in series])\n    return f"**{title}**{axes}\\n\\n{table}"\n\n\ndef _render_bar_chart_block(block: BarChartBlock) -> str:\n    if not block.bars:\n        return f"**{block.title}** *(aucune barre)*"\n    table = _markdown_table(\n        ["Catégorie", "Prévu", "Réel"],\n        [[b["label"], str(b["value"]), str(b["actual"]) if b["actual"] is not None else "—"] for b in block.bars],\n    )\n    return f"**{block.title}** ({block.y_axis_label})\\n\\n{table}"\n\n\ndef _render_checklist_block(block: ChecklistBlock) -> str:\n    return "\\n".join(\n        f"- [{\'x\' if item.get(\'checked\') else \' \'}] {item.get(\'text\', \'\')}"\n        for item in block.items\n    )\n\n\ndef _render_linked_checklist_block(block: LinkedChecklistBlock) -> str:\n    todo = "\\n".join(f"- [ ] {item.get(\'text\', \'\')}" for item in block.todo_items())\n    done = "\\n".join(f"- [x] {item.get(\'text\', \'\')}" for item in block.done_items())\n    parts = [p for p in ("**À faire**\\n" + todo, "**Faites**\\n" + done) if p.strip()]\n    return "\\n\\n".join(parts)\n\n\ndef _render_list_block(block: ListBlock) -> str:\n    if block.list_type == LIST_TYPE_NUMBERED:\n        return "\\n".join(f"{i + 1}. {item.get(\'text\', \'\')}" for i, item in enumerate(block.items))\n    return "\\n".join(f"- {item.get(\'text\', \'\')}" for item in block.items)\n\n\ndef _render_block(document, block) -> str:\n    if isinstance(block, HeadingBlock):\n        level = block.data.get("level", 1)\n        return f"{\'#\' * level} {block.content}"\n    if isinstance(block, TextBlock):\n        return block.content\n    if isinstance(block, ChecklistBlock):\n        return _render_checklist_block(block)\n    if isinstance(block, LinkedChecklistBlock):\n        return _render_linked_checklist_block(block)\n    if isinstance(block, ListBlock):\n        return _render_list_block(block)\n    if isinstance(block, TableBlock):\n        return _render_table_block(document, block)\n    if isinstance(block, SimpleTableBlock):\n        return _render_simple_table_block(block)\n    if isinstance(block, GanttBlock):\n        return _render_gantt_block(document, block)\n    if isinstance(block, DependencyGanttBlock):\n        return _render_dependency_gantt_block(document, block)\n    if isinstance(block, FormulaBlock):\n        return format_formula_text(block, compute_formula_result(document, block))\n    if isinstance(block, LineChartBlock):\n        return _render_line_chart_block(document, block)\n    if isinstance(block, BarChartBlock):\n        return _render_bar_chart_block(block)\n    if isinstance(block, ImageBlock):\n        if not block.data.get("image_base64"):\n            return "*(image vide)*"\n        fmt = block.data.get("format", "png")\n        return f"![](data:image/{fmt};base64,{block.data[\'image_base64\']})"\n    if isinstance(block, QuoteBlock):\n        return "\\n".join(f"> {line}" for line in (block.content or "").split("\\n")) or "> "\n    if isinstance(block, CodeBlock):\n        return f"```{block.language if block.language != \'text\' else \'\'}\\n{block.content}\\n```"\n    if isinstance(block, SeparatorBlock):\n        return "---"\n    return ""\n\n\ndef document_to_markdown(document) -> str:\n    """Convertit tout le document en Markdown, blocs séparés par une\n    ligne vide (obligatoire pour que le rendu Markdown standard\n    distingue correctement les blocs successifs, ex. deux tableaux)."""\n    parts = [_render_block(document, block) for block in document.blocks]\n    return "\\n\\n".join(part for part in parts if part)'
_SOURCES['core.document_markdown_import'] = '"""\nImport Markdown (PATCH 39).\n\nFonction pure `markdown_to_document(text)` : lit du Markdown standard\n(GitHub-flavored pour les tableaux et cases à cocher) et reconstruit\nun Document avec les blocs correspondants. Analyseur ligne par ligne,\nvolontairement simple (pas de dépendance externe), pensé pour\nretrouver au mieux les blocs produits par `document_to_markdown`\n(PATCH 37) — l\'aller-retour Markdown n\'est donc pas parfait pour du\nMarkdown écrit à la main dans un style très différent, mais couvre\nla syntaxe standard.\n"""\nfrom __future__ import annotations\n\nimport re\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.list_block import LIST_TYPE_BULLET, LIST_TYPE_NUMBERED, ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.separator_block import SeparatorBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.text_block import TextBlock\nfrom core.document import Document\n\n_HEADING_RE = re.compile(r"^(#{1,6})\\s+(.*)$")\n_TABLE_SEPARATOR_RE = re.compile(r"^\\s*\\|?[\\s:|-]+\\|[\\s:|-]*\\|?\\s*$")\n_CHECKLIST_RE = re.compile(r"^[-*]\\s+\\[( |x|X)\\]\\s+(.*)$")\n_HR_RE = re.compile(r"^(-{3,}|\\*{3,}|_{3,})$")\n_NUMBERED_RE = re.compile(r"^\\d+\\.\\s+(.*)$")\n_BULLET_RE = re.compile(r"^[-*]\\s+(.*)$")\n\n\ndef _split_table_row(line: str) -> list[str]:\n    stripped = line.strip()\n    if stripped.startswith("|"):\n        stripped = stripped[1:]\n    if stripped.endswith("|"):\n        stripped = stripped[:-1]\n    return [cell.strip() for cell in stripped.split("|")]\n\n\ndef markdown_to_document(text: str) -> Document:\n    """Reconstruit un Document à partir d\'une chaîne Markdown."""\n    document = Document()\n    lines = text.splitlines()\n    i = 0\n    n = len(lines)\n\n    while i < n:\n        line = lines[i]\n\n        if not line.strip():\n            i += 1\n            continue\n\n        # Bloc de code : ```langage ... ```\n        if line.strip().startswith("```"):\n            language = line.strip()[3:].strip() or "text"\n            i += 1\n            code_lines: list[str] = []\n            while i < n and not lines[i].strip().startswith("```"):\n                code_lines.append(lines[i])\n                i += 1\n            i += 1  # saute la clôture ```\n            document.add_block(CodeBlock(content="\\n".join(code_lines), language=language))\n            continue\n\n        # Titre : # à ###### (les niveaux > 3 sont ramenés à 3, HeadingBlock\n        # ne supportant que H1-H3).\n        heading_match = _HEADING_RE.match(line)\n        if heading_match:\n            level = min(len(heading_match.group(1)), 3)\n            document.add_block(HeadingBlock(level=level, content=heading_match.group(2).strip()))\n            i += 1\n            continue\n\n        # Tableau : ligne d\'en-tête "|...|" suivie d\'une ligne séparatrice.\n        if line.strip().startswith("|") and i + 1 < n and _TABLE_SEPARATOR_RE.match(lines[i + 1]):\n            table_rows = [_split_table_row(line)]\n            i += 2  # saute l\'en-tête + la ligne séparatrice\n            while i < n and lines[i].strip().startswith("|"):\n                table_rows.append(_split_table_row(lines[i]))\n                i += 1\n            document.add_block(SimpleTableBlock(rows=table_rows))\n            continue\n\n        # Checklist : "- [ ] texte" / "- [x] texte" (avant la liste à puces,\n        # dont c\'est un cas particulier).\n        if _CHECKLIST_RE.match(line):\n            block = ChecklistBlock()\n            while i < n:\n                match = _CHECKLIST_RE.match(lines[i])\n                if not match:\n                    break\n                block.add_item(match.group(2), checked=match.group(1).lower() == "x")\n                i += 1\n            document.add_block(block)\n            continue\n\n        # Séparateur : ligne de tirets/astérisques seule.\n        if _HR_RE.match(line.strip()):\n            document.add_block(SeparatorBlock())\n            i += 1\n            continue\n\n        # Liste numérotée : "1. texte", "2. texte", ...\n        if _NUMBERED_RE.match(line):\n            block = ListBlock(list_type=LIST_TYPE_NUMBERED)\n            while i < n:\n                match = _NUMBERED_RE.match(lines[i])\n                if not match:\n                    break\n                block.add_item(match.group(1))\n                i += 1\n            document.add_block(block)\n            continue\n\n        # Liste à puces : "- texte" / "* texte" (hors case à cocher, déjà géré).\n        if _BULLET_RE.match(line) and not _CHECKLIST_RE.match(line):\n            block = ListBlock(list_type=LIST_TYPE_BULLET)\n            while i < n:\n                if _CHECKLIST_RE.match(lines[i]):\n                    break\n                match = _BULLET_RE.match(lines[i])\n                if not match:\n                    break\n                block.add_item(match.group(1))\n                i += 1\n            document.add_block(block)\n            continue\n\n        # Citation : lignes commençant par ">"\n        if line.strip().startswith(">"):\n            quote_lines = []\n            while i < n and lines[i].strip().startswith(">"):\n                quote_lines.append(re.sub(r"^\\s*>\\s?", "", lines[i]))\n                i += 1\n            document.add_block(QuoteBlock(content="\\n".join(quote_lines)))\n            continue\n\n        # Paragraphe : lignes consécutives non vides -> bloc Texte.\n        paragraph_lines = []\n        while i < n and lines[i].strip():\n            paragraph_lines.append(lines[i])\n            i += 1\n        document.add_block(TextBlock(content="\\n".join(paragraph_lines)))\n\n    return document\n'
_SOURCES['core.duration'] = '"""\nSystème de durée (PATCH 17).\n\nUne durée est représentée par {"amount": int, "unit": str}, avec\n`unit` parmi DURATION_UNITS ("heures", "jours", "semaines") — voir\n`blocks/table_block.py` (colonne "Durée", introduite au PATCH 15).\n\nCe module fournit le moteur indépendant de l\'UI :\n    - format_duration : représentation lisible ("2 semaines", "1 jour").\n    - parse_duration_text : lecture d\'une saisie libre ("2 semaines",\n      "3h", "1j") vers {"amount", "unit"}.\n    - to_hours : conversion en heures, pour comparer/additionner des\n      durées d\'unités différentes (utile à la vue Gantt du PATCH 19).\n\nConversion retenue (calendaire, pas en jours ouvrés) :\n    1 jour = 24 heures, 1 semaine = 7 jours = 168 heures.\n"""\nfrom __future__ import annotations\n\nimport re\nfrom typing import Optional\n\nHOURS_PER_UNIT: dict[str, int] = {"heures": 1, "jours": 24, "semaines": 168}\n\n# Alias reconnus en saisie libre, vers l\'unité canonique.\n_UNIT_ALIASES: dict[str, str] = {\n    "h": "heures", "heure": "heures", "heures": "heures",\n    "j": "jours", "jour": "jours", "jours": "jours",\n    "s": "semaines", "sem": "semaines", "semaine": "semaines", "semaines": "semaines",\n}\n\n_PARSE_RE = re.compile(r"^\\s*(\\d+)\\s*([a-zA-Zéèê]+)\\s*$")\n\n\ndef format_duration(duration: dict) -> str:\n    """Formate une durée en texte lisible, avec accord singulier/pluriel.\n\n    Ex. : {"amount": 1, "unit": "jours"} -> "1 jour"\n          {"amount": 2, "unit": "semaines"} -> "2 semaines"\n    """\n    amount = int(duration.get("amount", 0))\n    unit = duration.get("unit", "jours")\n    singular = {"heures": "heure", "jours": "jour", "semaines": "semaine"}.get(unit, unit)\n    label = singular if amount == 1 else unit\n    return f"{amount} {label}"\n\n\ndef parse_duration_text(text: str) -> Optional[dict]:\n    """Interprète une saisie libre ("2 semaines", "3h", "1 j") en durée.\n\n    Retourne None si le texte ne correspond à aucun format reconnu.\n    """\n    match = _PARSE_RE.match(text or "")\n    if not match:\n        return None\n    amount_str, unit_str = match.groups()\n    unit = _UNIT_ALIASES.get(unit_str.lower())\n    if unit is None:\n        return None\n    return {"amount": int(amount_str), "unit": unit}\n\n\ndef to_hours(duration: dict) -> int:\n    """Convertit une durée en nombre d\'heures (base de comparaison commune)."""\n    amount = int(duration.get("amount", 0))\n    unit = duration.get("unit", "jours")\n    return amount * HOURS_PER_UNIT.get(unit, HOURS_PER_UNIT["jours"])\n'
_SOURCES['core.emoji_data'] = '"""\nSupport des emojis (PATCH 35).\n\nFonctions pures (indépendantes de Qt) : liste catégorisée d\'emojis\navec leur "shortcode" façon Slack/Discord (ex. ``:smile:`` -> 😄),\nrecherche par nom/shortcode, et résolution d\'un shortcode tapé au\nclavier.\n"""\nfrom __future__ import annotations\n\nimport re\n\n# (emoji, shortcode, catégorie) — liste volontairement compacte mais\n# couvrant les usages courants d\'une prise de notes.\nEMOJIS: list[tuple[str, str, str]] = [\n    ("😀", "grinning", "Émotions"),\n    ("😄", "smile", "Émotions"),\n    ("😂", "joy", "Émotions"),\n    ("🙂", "slight_smile", "Émotions"),\n    ("😉", "wink", "Émotions"),\n    ("😍", "heart_eyes", "Émotions"),\n    ("😢", "cry", "Émotions"),\n    ("😡", "angry", "Émotions"),\n    ("😱", "scream", "Émotions"),\n    ("🤔", "thinking", "Émotions"),\n    ("👍", "thumbsup", "Gestes"),\n    ("👎", "thumbsdown", "Gestes"),\n    ("👏", "clap", "Gestes"),\n    ("🙏", "pray", "Gestes"),\n    ("💪", "muscle", "Gestes"),\n    ("✅", "white_check_mark", "Symboles"),\n    ("❌", "x", "Symboles"),\n    ("⚠️", "warning", "Symboles"),\n    ("⭐", "star", "Symboles"),\n    ("🔥", "fire", "Symboles"),\n    ("💡", "bulb", "Symboles"),\n    ("📌", "pushpin", "Symboles"),\n    ("📎", "paperclip", "Symboles"),\n    ("📅", "calendar", "Objets"),\n    ("⏰", "alarm_clock", "Objets"),\n    ("📝", "memo", "Objets"),\n    ("📊", "bar_chart", "Objets"),\n    ("💻", "computer", "Objets"),\n    ("📁", "file_folder", "Objets"),\n    ("🚀", "rocket", "Objets"),\n    ("🎉", "tada", "Objets"),\n    ("☕", "coffee", "Objets"),\n    ("🍕", "pizza", "Objets"),\n]\n\n_SHORTCODE_RE = re.compile(r":([a-zA-Z0-9_+\\-]+):$")\n_SHORTCODE_TO_EMOJI: dict[str, str] = {shortcode: emoji for emoji, shortcode, _ in EMOJIS}\n\n\ndef search_emojis(query: str) -> list[tuple[str, str, str]]:\n    """Filtre EMOJIS dont le shortcode contient `query` (insensible à la casse)."""\n    query = (query or "").strip().lower()\n    if not query:\n        return list(EMOJIS)\n    return [item for item in EMOJIS if query in item[1].lower()]\n\n\ndef shortcode_to_emoji(shortcode: str) -> str | None:\n    """Résout un shortcode exact (sans les \':\') vers son emoji, ou None."""\n    return _SHORTCODE_TO_EMOJI.get(shortcode)\n\n\ndef resolve_trailing_shortcode(text: str) -> tuple[str, str] | None:\n    """Si `text` se termine par un shortcode complet (ex. "Salut :smile:"),\n    retourne (texte_avec_emoji, emoji_inséré). None sinon ou si le\n    shortcode est inconnu.\n\n    Utilisé pour la conversion automatique façon Slack/Discord au fil\n    de la frappe : dès que l\'utilisateur tape le ":" fermant, le\n    shortcode reconnu est remplacé par l\'emoji correspondant.\n    """\n    match = _SHORTCODE_RE.search(text)\n    if not match:\n        return None\n    emoji = shortcode_to_emoji(match.group(1))\n    if emoji is None:\n        return None\n    new_text = text[: match.start()] + emoji\n    return new_text, emoji\n'
_SOURCES['core.history'] = '"""\nHistorique Undo/Redo (PATCH 27).\n\nPile de snapshots (chaînes JSON) du document, agnostique de Qt et du\ncontenu réel des blocs — donc facilement testable seule. Un\n"snapshot" est la sérialisation complète du document\n(``Document.to_dict()``, cf. PATCH 8/9), ce qui garantit un état\ntotalement indépendant de l\'état courant, quel que soit le type de\nbloc modifié (texte, checklist, tableau, image, ...).\n"""\nfrom __future__ import annotations\n\n_DEFAULT_MAX_HISTORY = 200\n\n\nclass UndoHistory:\n    """Pile undo/redo générique basée sur des snapshots texte.\n\n    Utilisation typique :\n        history = UndoHistory(snapshot())\n        ... l\'utilisateur modifie le document ...\n        history.check(snapshot())   # crée un point d\'annulation si besoin\n        ...\n        previous = history.undo(snapshot())  # None si rien à annuler\n        next_ = history.redo()               # None si rien à rétablir\n    """\n\n    def __init__(self, initial_snapshot: str, max_history: int = _DEFAULT_MAX_HISTORY) -> None:\n        self._baseline = initial_snapshot\n        self._undo_stack: list[str] = []\n        self._redo_stack: list[str] = []\n        self._max_history = max_history\n\n    @property\n    def baseline(self) -> str:\n        """Dernier snapshot connu comme étant l\'état courant "propre"."""\n        return self._baseline\n\n    def can_undo(self) -> bool:\n        return bool(self._undo_stack)\n\n    def can_redo(self) -> bool:\n        return bool(self._redo_stack)\n\n    def check(self, current_snapshot: str) -> bool:\n        """Crée un point d\'annulation si `current_snapshot` diffère de\n        la référence courante. Retourne True si un point a été créé.\n\n        Vide la pile de rétablissement (toute nouvelle action rend les\n        anciens "redo" obsolètes — comportement standard).\n        """\n        if current_snapshot == self._baseline:\n            return False\n        self._undo_stack.append(self._baseline)\n        if len(self._undo_stack) > self._max_history:\n            self._undo_stack.pop(0)\n        self._redo_stack.clear()\n        self._baseline = current_snapshot\n        return True\n\n    def undo(self, current_snapshot: str) -> str | None:\n        """Confirme d\'abord tout changement en attente (`current_snapshot`),\n        puis dépile un état antérieur. None si rien à annuler."""\n        self.check(current_snapshot)\n        if not self._undo_stack:\n            return None\n        self._redo_stack.append(self._baseline)\n        self._baseline = self._undo_stack.pop()\n        return self._baseline\n\n    def redo(self) -> str | None:\n        """Rétablit le dernier état annulé. None si rien à rétablir."""\n        if not self._redo_stack:\n            return None\n        self._undo_stack.append(self._baseline)\n        if len(self._undo_stack) > self._max_history:\n            self._undo_stack.pop(0)\n        self._baseline = self._redo_stack.pop()\n        return self._baseline\n'
_SOURCES['core.people_registry'] = '"""\nRegistre système des personnes (PATCH 82).\n\nAvant ce patch, chaque document stockait sa propre copie complète des\npersonnes (id, nom, couleur) dans son JSON. Deux projets différents ne\npartageaient donc rien : ajouter "Alice" dans un projet ne la rendait\npas disponible dans un autre, et une même personne pouvait finir avec\ndes couleurs différentes d\'un fichier à l\'autre — la source de la\n"gestion très buggée" des personnes.\n\nCe module introduit un fichier système unique par utilisateur\n(~/.methodo-og/people.json par défaut, indépendant de tout projet)\nqui devient la seule source de vérité pour le nom et la couleur d\'une\npersonne. Un `Document` ne conserve plus que la liste des identifiants\nde personnes qu\'il référence (voir `core.document.Document`), et\ndélègue toute lecture/écriture de nom/couleur à ce registre partagé.\n\nAjouter une personne depuis n\'importe quel projet la rend donc\nimmédiatement disponible dans tous les autres.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nimport uuid\nfrom pathlib import Path\nfrom typing import Any, Optional\n\nREGISTRY_FORMAT_VERSION = 1\n\n# Variable d\'environnement permettant de surcharger l\'emplacement du\n# registre (tests automatisés, installations portables/multi-poste).\n_ENV_OVERRIDE = "METHODO_OG_PEOPLE_FILE"\n\n# Palette assignée automatiquement (par rotation) aux nouvelles personnes.\nPERSON_COLOR_PALETTE: list[str] = [\n    "#e57373", "#64b5f6", "#81c784", "#ffd54f",\n    "#ba68c8", "#4db6ac", "#f06292", "#a1887f",\n]\n\n\ndef default_registry_path() -> Path:\n    """Emplacement système par défaut du registre partagé des personnes.\n\n    Surchargeable via la variable d\'environnement METHODO_OG_PEOPLE_FILE\n    (utilisé notamment par les tests, pour ne jamais toucher au vrai\n    fichier de l\'utilisateur qui exécute la suite).\n    """\n    override = os.environ.get(_ENV_OVERRIDE)\n    if override:\n        return Path(override)\n    return Path.home() / ".methodo-og" / "people.json"\n\n\nclass PeopleRegistry:\n    """Registre des personnes connues, persisté dans un unique fichier\n    JSON système, partagé par tous les projets Méthodo OG de l\'utilisateur.\n    """\n\n    def __init__(self, path: Path | None = None, *, autoload: bool = True) -> None:\n        self.path = path or default_registry_path()\n        self._people: list[dict[str, Any]] = []\n        if autoload:\n            self.load()\n\n    # -- Persistance --------------------------------------------------\n\n    def load(self) -> None:\n        """(Re)charge le registre depuis le disque. Silencieux si le\n        fichier n\'existe pas encore (première utilisation) ou est\n        corrompu (on repart alors d\'un registre vide plutôt que de\n        planter au démarrage)."""\n        if not self.path.exists():\n            self._people = []\n            return\n        try:\n            raw = json.loads(self.path.read_text(encoding="utf-8"))\n        except (OSError, ValueError):\n            self._people = []\n            return\n        self._people = [\n            {\n                "id": person.get("id") or str(uuid.uuid4()),\n                "name": person.get("name", ""),\n                "color": person.get("color") or PERSON_COLOR_PALETTE[0],\n            }\n            for person in raw.get("people", [])\n        ]\n\n    def save(self) -> None:\n        """Écrit le registre sur disque, en créant le dossier système\n        (~/.methodo-og par défaut) si besoin."""\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        payload = {"version": REGISTRY_FORMAT_VERSION, "people": self._people}\n        self.path.write_text(\n            json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8"\n        )\n\n    # -- Lecture ----------------------------------------------------------\n\n    @property\n    def people(self) -> list[dict[str, Any]]:\n        """Toutes les personnes connues, tous projets confondus."""\n        return list(self._people)\n\n    def find_person(self, person_id: str) -> Optional[dict[str, Any]]:\n        for person in self._people:\n            if person["id"] == person_id:\n                return person\n        return None\n\n    def find_by_name(self, name: str) -> Optional[dict[str, Any]]:\n        """Recherche insensible à la casse/espaces, pour éviter que\n        deux projets créent chacun un doublon "Alice" / "alice " par\n        simple étourderie."""\n        needle = name.strip().casefold()\n        for person in self._people:\n            if person["name"].strip().casefold() == needle:\n                return person\n        return None\n\n    # -- Écriture -----------------------------------------------------\n\n    def add_person(self, name: str, color: str | None = None) -> dict[str, Any]:\n        """Ajoute une personne, ou retourne celle qui existe déjà sous\n        ce nom (le registre est global : pas de doublon involontaire\n        entre deux projets)."""\n        existing = self.find_by_name(name)\n        if existing is not None:\n            return existing\n        if color is None:\n            color = PERSON_COLOR_PALETTE[len(self._people) % len(PERSON_COLOR_PALETTE)]\n        person = {"id": str(uuid.uuid4()), "name": name, "color": color}\n        self._people.append(person)\n        self.save()\n        return person\n\n    def rename_person(self, person_id: str, name: str) -> bool:\n        person = self.find_person(person_id)\n        if person is None:\n            return False\n        person["name"] = name\n        self.save()\n        return True\n\n    def set_person_color(self, person_id: str, color: str) -> bool:\n        person = self.find_person(person_id)\n        if person is None:\n            return False\n        person["color"] = color\n        self.save()\n        return True\n\n    def remove_person(self, person_id: str) -> bool:\n        """Supprime définitivement la personne du registre partagé\n        (donc de tous les projets qui la référencent). Voir\n        `Document.remove_person` pour le retrait "local" à un seul\n        projet, qui ne touche pas au registre."""\n        person = self.find_person(person_id)\n        if person is None:\n            return False\n        self._people.remove(person)\n        self.save()\n        return True\n'
_SOURCES['core.project_meta'] = '"""\nMétadonnées système d\'un projet (PATCH 82).\n\nAvant ce patch, le "nom du projet" affiché (titre de fenêtre, projets\nrécents) n\'était jamais que le nom du fichier .json sur disque : le\nrenommer, le déplacer ou le dupliquer changeait donc silencieusement\nl\'identité du projet aux yeux de l\'application.\n\nCe module introduit un petit fichier système séparé,\n".methodo-project.json", posé à côté du fichier .json dans le dossier\ndu projet. Il porte le nom "métier" du projet (et sa date de création,\nson identifiant stable) indépendamment du nom de fichier utilisé pour\nle stockage : renommer le fichier .json, ou le dossier qui le contient,\nne change plus le nom du projet.\n\nCe fichier commence par un point : les explorateurs (dont celui de\nMéthodo OG, PATCH 81, basé sur QFileSystemModel) le masquent par\ndéfaut, comme le ferait un ".git" ou un ".vscode".\n"""\nfrom __future__ import annotations\n\nimport json\nimport uuid\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Any, Optional\n\nMETA_FORMAT_VERSION = 1\nMETA_FILENAME = ".methodo-project.json"\n\n\ndef meta_path_for(document_path: Path) -> Path:\n    """Chemin du fichier système de métadonnées associé au projet\n    contenant `document_path` (un seul projet = un seul dossier, PATCH\n    66) : toujours ".methodo-project.json" dans ce même dossier, quel\n    que soit le nom du fichier .json lui-même."""\n    return document_path.parent / META_FILENAME\n\n\n@dataclass\nclass ProjectMeta:\n    """Informations "système" d\'un projet, séparées du contenu du\n    document (blocs, personnes) et du nom de son fichier de stockage."""\n\n    id: str\n    name: str\n    created_at: str\n\n    @classmethod\n    def create(cls, name: str) -> "ProjectMeta":\n        return cls(\n            id=str(uuid.uuid4()),\n            name=name,\n            created_at=datetime.now(timezone.utc).isoformat(timespec="seconds"),\n        )\n\n    def to_dict(self) -> dict[str, Any]:\n        return {\n            "version": META_FORMAT_VERSION,\n            "id": self.id,\n            "name": self.name,\n            "created_at": self.created_at,\n        }\n\n    @classmethod\n    def from_dict(cls, raw: dict[str, Any]) -> "ProjectMeta":\n        return cls(\n            id=raw.get("id") or str(uuid.uuid4()),\n            name=raw.get("name", ""),\n            created_at=raw.get("created_at", ""),\n        )\n\n    # -- Persistance --------------------------------------------------\n\n    def save(self, document_path: Path) -> None:\n        meta_path_for(document_path).write_text(\n            json.dumps(self.to_dict(), ensure_ascii=False, indent=2), encoding="utf-8"\n        )\n\n    @classmethod\n    def load(cls, document_path: Path) -> Optional["ProjectMeta"]:\n        """Charge les métadonnées existantes du projet, ou None si le\n        fichier système est absent ou illisible (projet créé avant ce\n        patch, fichier corrompu...)."""\n        path = meta_path_for(document_path)\n        if not path.exists():\n            return None\n        try:\n            return cls.from_dict(json.loads(path.read_text(encoding="utf-8")))\n        except (OSError, ValueError):\n            return None\n\n    @classmethod\n    def load_or_create(cls, document_path: Path, default_name: str | None = None) -> "ProjectMeta":\n        """Charge les métadonnées si elles existent déjà, sinon en crée\n        et persiste de nouvelles à partir d\'un nom par défaut\n        (rétrocompatibilité avec les projets créés avant ce patch, qui\n        n\'ont pas encore de fichier système : ils en reçoivent un dès\n        leur prochaine ouverture, avec leur nom de fichier actuel comme\n        nom de projet initial)."""\n        existing = cls.load(document_path)\n        if existing is not None:\n            return existing\n        meta = cls.create(default_name or document_path.stem)\n        meta.save(document_path)\n        return meta\n\n    def rename(self, document_path: Path, new_name: str) -> None:\n        """Renomme le projet (nom "métier" uniquement) sans toucher au\n        fichier .json ni à son emplacement."""\n        self.name = new_name\n        self.save(document_path)\n'
_SOURCES['core.project_template'] = '"""\nTemplate par défaut "Modèle OG" (Opportunity Governance, PATCH 48).\n\nConstruit un Document complet illustrant l\'ensemble des blocs du\nprojet : titres, effectif, checklists liées, tableau de critères\nnoté avec résultat calculé, tableau d\'assignation de tâches relié à\nun planning par dépendances, et deux graphiques (courbes\n"Efficacité" et bâtonnets "Delta de budget").\n\nToutes les valeurs d\'exemple (noms, critères, tâches, montants) sont\narbitraires et destinées à être modifiées par l\'utilisateur.\n"""\nfrom __future__ import annotations\n\nimport random\n\nfrom blocks.bar_chart_block import BarChartBlock\nfrom blocks.dependency_gantt_block import DependencyGanttBlock\nfrom blocks.formula_block import FormulaBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.line_chart_block import SLOPE_MODE_CONSTANT, SLOPE_MODE_EFFICIENCY, LineChartBlock\nfrom blocks.linked_checklist_block import LinkedChecklistBlock\nfrom blocks.people_list_block import PeopleListBlock\nfrom blocks.table_block import (\n    COLUMN_TYPE_BOOLEAN,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_PERSON,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_TEXT,\n    TableBlock,\n)\nfrom blocks.text_block import TextBlock\nfrom core.document import Document\n\n# Vivier de noms utilisé pour tirer l\'effectif d\'exemple au hasard\n# (PATCH 48) : trois noms différents à chaque nouveau document créé\n# depuis ce template.\n_SAMPLE_NAMES = [\n    "Camille Dupont",\n    "Yanis Bernard",\n    "Lina Rousseau",\n    "Hugo Lefevre",\n    "Nora Girard",\n    "Théo Morel",\n    "Chloé Fontaine",\n    "Adam Perrin",\n]\n\n_RISK_OPTIONS = ["vert", "orange", "rouge"]\n\n\ndef build_project_template() -> Document:\n    """Construit un nouveau Document à partir du template "Modèle OG" (Opportunity Governance)."""\n    document = Document()\n\n    # -- Titre + Effectif -------------------------------------------------\n    document.add_block(HeadingBlock(level=1, content="Modèle OG"))\n    document.add_block(HeadingBlock(level=2, content="Effectif"))\n\n    names = random.sample(_SAMPLE_NAMES, 3)\n    people = [document.add_person(name) for name in names]\n    # PATCH 52 — L\'effectif est désormais un bloc "people_list" éditable\n    # (ajout par Entrée), vue directe du registre partagé Document.people,\n    # synchronisée avec le Gestionnaire de personnes.\n    document.add_block(PeopleListBlock())\n\n    # -- Checklist initiale (deux checklists liées) ------------------------\n    document.add_block(HeadingBlock(level=2, content="Checklist initiale"))\n    checklist = LinkedChecklistBlock()\n    for label in ("A", "B", "C"):\n        checklist.add_item(text=label)\n    document.add_block(checklist)\n\n    # -- Critères (tableau noté + résultat calculé) ------------------------\n    document.add_block(HeadingBlock(level=2, content="Critères"))\n    criteria_table = TableBlock()\n    cat_col = criteria_table.add_column("Catégorie", col_type=COLUMN_TYPE_TEXT)\n    state_col = criteria_table.add_column("Etat", col_type=COLUMN_TYPE_BOOLEAN)\n    points_col = criteria_table.add_column("Points", col_type=COLUMN_TYPE_NUMBER)\n    details_col = criteria_table.add_column("Détails", col_type=COLUMN_TYPE_TEXT)\n    for cat, state, points, details in (\n        ("Qualité du code", True, "5", "Revue effectuée, conventions respectées"),\n        ("Tests automatisés", False, "3", "Couverture partielle à compléter"),\n        ("Documentation", True, "2", "README à jour"),\n    ):\n        criteria_table.add_row(\n            values={\n                cat_col["id"]: cat,\n                state_col["id"]: state,\n                points_col["id"]: points,\n                details_col["id"]: details,\n            }\n        )\n    document.add_block(criteria_table)\n\n    result_block = FormulaBlock(\n        table_block_id=criteria_table.id,\n        number_column_id=points_col["id"],\n        boolean_column_id=state_col["id"],\n        label="Résultat: ",\n    )\n    document.add_block(result_block)\n\n    # -- Assignation des tâches (planning par dépendances) -----------------\n    document.add_block(HeadingBlock(level=2, content="Assignation des tâches"))\n    tasks_table = TableBlock()\n    phase_col = tasks_table.add_column("Phases", col_type=COLUMN_TYPE_TEXT)\n    subtask_col = tasks_table.add_column("Sous-tâches", col_type=COLUMN_TYPE_TEXT)\n    assignee_col = tasks_table.add_column("Prsn. assignées", col_type=COLUMN_TYPE_PERSON)\n    duration_col = tasks_table.add_column("Temps estimé (jours)", col_type=COLUMN_TYPE_NUMBER)\n    risk_col = tasks_table.add_column("Risques", col_type=COLUMN_TYPE_SELECT, options=list(_RISK_OPTIONS))\n    dependency_col = tasks_table.add_column("Dépendances", col_type=COLUMN_TYPE_MULTI_SELECT)\n    delta_col = tasks_table.add_column("Ecarts", col_type=COLUMN_TYPE_NUMBER)\n    # PATCH 59 — colonnes "Prix" utilisées par le graphique "Delta de\n    # budget" (voir plus bas) à la place de la durée/l\'écart en jours.\n    price_estimated_col = tasks_table.add_column("Prix estimé", col_type=COLUMN_TYPE_NUMBER, unit="€")\n    price_actual_col = tasks_table.add_column("Prix réel", col_type=COLUMN_TYPE_NUMBER, unit="€")\n\n    example_tasks = [\n        # (phase, sous-tâche, assignés, durée, risque, dépendances, écart, prix estimé, prix réel)\n        ("Phase 1", "Conception", [people[0]["id"]], "3", "vert", [], "0", "900", "900"),\n        ("Phase 1", "Maquettes", [people[1]["id"]], "2", "orange", ["Conception"], "0", "600", "650"),\n        ("Phase 2", "Développement", [people[1]["id"], people[2]["id"]], "5", "orange", ["Maquettes"], "0", "1500", "1500"),\n        ("Phase 2", "Tests", [people[2]["id"]], "2.5", "rouge", ["Développement"], "0", "750", "700"),\n    ]\n    subtask_labels = [row[1] for row in example_tasks]\n    tasks_table.set_column_options(dependency_col["id"], subtask_labels)\n\n    for phase, subtask, assignees, duration, risk, dependencies, ecart, price_estimated, price_actual in example_tasks:\n        tasks_table.add_row(\n            values={\n                phase_col["id"]: phase,\n                subtask_col["id"]: subtask,\n                assignee_col["id"]: assignees,\n                duration_col["id"]: duration,\n                risk_col["id"]: risk,\n                dependency_col["id"]: dependencies,\n                delta_col["id"]: ecart,\n                price_estimated_col["id"]: price_estimated,\n                price_actual_col["id"]: price_actual,\n            }\n        )\n    document.add_block(tasks_table)\n\n    gantt = DependencyGanttBlock(\n        table_block_id=tasks_table.id,\n        label_column_id=subtask_col["id"],\n        person_column_id=assignee_col["id"],\n        duration_column_id=duration_col["id"],\n        risk_column_id=risk_col["id"],\n        dependency_column_id=dependency_col["id"],\n        delta_column_id=delta_col["id"],\n    )\n    document.add_block(gantt)\n\n    # -- Graphique "Efficacité" ---------------------------------------------\n    efficiency_chart = LineChartBlock(\n        title="Efficacité", x_axis_label="Temps", y_axis_label="Avancement moyen", x_max=12\n    )\n    efficiency_chart.add_series(name="Idéal", mode=SLOPE_MODE_CONSTANT, slope=1.0, color="#43a047")\n    # Constante de vélocité arbitraire, à ajuster par l\'utilisateur.\n    efficiency_chart.add_series(name="Vélocité", mode=SLOPE_MODE_CONSTANT, slope=0.8, color="#fb8c00")\n    efficiency_chart.add_series(\n        name="Vélocité réelle",\n        mode=SLOPE_MODE_EFFICIENCY,\n        source_block_id=gantt.id,\n        color="#1976d2",\n    )\n    document.add_block(efficiency_chart)\n\n    # -- Graphique "Delta de budget" (une barre par phase, synchronisée en\n    # direct — PATCH 54, PATCH 59 — avec les colonnes "Prix estimé"/"Prix\n    # réel" du planning par dépendances ci-dessus, regroupées par\n    # "Phases") -------------------------------------------------------------\n    budget_chart = BarChartBlock(title="Delta de budget", y_axis_label="Prix")\n    budget_chart.set_source(gantt.id, phase_col["id"], price_estimated_col["id"], price_actual_col["id"])\n    document.add_block(budget_chart)\n\n    return document'
_SOURCES['core.replace'] = '"""\nRemplacement de texte (PATCH 29).\n\nFonction pure, indépendante de Qt, construite sur les mêmes\ncatégories de blocs que la recherche globale (PATCH 28) :\ntexte/titres/citation/code, checklists, listes, et les deux moteurs\nde tableau (PATCH 14 typé et PATCH 24 simple).\n\nDans le tableau typé (PATCH 15), seules les colonnes dont la valeur\nest du texte simple sont concernées (texte, nombre, liste déroulante,\nliste multiple, éléments d\'une checklist imbriquée). Les colonnes\nPersonne sont volontairement exclues : les renommer doit passer par\nle gestionnaire de personnes (PATCH 16) pour rester synchronisé avec\nle registre partagé. Les colonnes Date/Durée/Booléen ne sont pas\ntextuelles et ne sont donc pas concernées.\n"""\nfrom __future__ import annotations\n\nimport re\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.list_block import ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import (\n    COLUMN_TYPE_CHECKLIST,\n    COLUMN_TYPE_MULTI_SELECT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_SELECT,\n    COLUMN_TYPE_TEXT,\n    TableBlock,\n)\nfrom blocks.text_block import TextBlock\nfrom core.document import Document\n\n_TEXTUAL_COLUMN_TYPES = {\n    COLUMN_TYPE_TEXT,\n    COLUMN_TYPE_NUMBER,\n    COLUMN_TYPE_SELECT,\n}\n_LIST_OF_TEXT_COLUMN_TYPES = {COLUMN_TYPE_MULTI_SELECT}\n\n\ndef _replace_in_text(text: str, pattern: re.Pattern, replacement: str) -> tuple[str, int]:\n    count = len(pattern.findall(text))\n    if count == 0:\n        return text, 0\n    return pattern.sub(lambda _match: replacement, text), count\n\n\ndef replace_all(document: Document, query: str, replacement: str) -> int:\n    """Remplace toutes les occurrences (insensible à la casse) de\n    `query` par `replacement` dans tout le document.\n\n    Retourne le nombre total d\'occurrences remplacées.\n    """\n    query = (query or "").strip()\n    if not query:\n        return 0\n    pattern = re.compile(re.escape(query), re.IGNORECASE)\n    total = 0\n\n    for block in document.blocks:\n        if isinstance(block, (TextBlock, HeadingBlock, QuoteBlock, CodeBlock)):\n            new_content, count = _replace_in_text(block.content, pattern, replacement)\n            if count:\n                block.content = new_content\n                total += count\n                if isinstance(block, TextBlock) and block.html:\n                    # La mise en forme riche (PATCH 6) porte sur l\'ancien\n                    # texte : on l\'efface plutôt que de la laisser\n                    # désynchronisée du nouveau contenu.\n                    block.html = ""\n\n        elif isinstance(block, ChecklistBlock):\n            for item in block.items:\n                new_text, count = _replace_in_text(item.get("text", ""), pattern, replacement)\n                if count:\n                    item["text"] = new_text\n                    total += count\n\n        elif isinstance(block, ListBlock):\n            for item in block.items:\n                new_text, count = _replace_in_text(item.get("text", ""), pattern, replacement)\n                if count:\n                    item["text"] = new_text\n                    total += count\n\n        elif isinstance(block, TableBlock):\n            total += _replace_in_table(block, pattern, replacement)\n\n        elif isinstance(block, SimpleTableBlock):\n            for row_index, row in enumerate(block.rows):\n                for col_index, cell in enumerate(row):\n                    new_cell, count = _replace_in_text(cell, pattern, replacement)\n                    if count:\n                        block.set_cell(row_index, col_index, new_cell)\n                        total += count\n\n    return total\n\n\ndef _replace_in_table(block: TableBlock, pattern: re.Pattern, replacement: str) -> int:\n    total = 0\n    for row in block.rows:\n        for column in block.columns:\n            col_type = column.get("type")\n            value = block.get_cell(row["id"], column["id"])\n\n            if col_type in _TEXTUAL_COLUMN_TYPES and isinstance(value, str):\n                new_value, count = _replace_in_text(value, pattern, replacement)\n                if count:\n                    block.set_cell(row["id"], column["id"], new_value)\n                    total += count\n\n            elif col_type in _LIST_OF_TEXT_COLUMN_TYPES and isinstance(value, list):\n                new_values = []\n                changed = False\n                for entry in value:\n                    new_entry, count = _replace_in_text(str(entry), pattern, replacement)\n                    if count:\n                        changed = True\n                        total += count\n                    new_values.append(new_entry)\n                if changed:\n                    block.set_cell(row["id"], column["id"], new_values)\n\n            elif col_type == COLUMN_TYPE_CHECKLIST and isinstance(value, list):\n                changed = False\n                for entry in value:\n                    if not isinstance(entry, dict):\n                        continue\n                    new_text, count = _replace_in_text(entry.get("text", ""), pattern, replacement)\n                    if count:\n                        entry["text"] = new_text\n                        changed = True\n                        total += count\n                if changed:\n                    block.set_cell(row["id"], column["id"], value)\n\n    return total\n'
_SOURCES['core.search'] = '"""\nRecherche globale (PATCH 28).\n\nFonction pure, indépendante de Qt : parcourt tous les blocs du\ndocument et retourne les correspondances sous forme de\n`SearchResult`, pour rester facilement testable sans interface\ngraphique. Couvre le texte (texte, titres, citation, code), les\nchecklists, les listes et les deux moteurs de tableau (PATCH 14 et\nPATCH 24).\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\n\nfrom blocks.checklist_block import ChecklistBlock\nfrom blocks.code_block import CodeBlock\nfrom blocks.heading_block import HeadingBlock\nfrom blocks.list_block import ListBlock\nfrom blocks.quote_block import QuoteBlock\nfrom blocks.simple_table_block import SimpleTableBlock\nfrom blocks.table_block import TableBlock\nfrom blocks.text_block import TextBlock\nfrom core.document import Document\n\n_SNIPPET_RADIUS = 30\n\n\n@dataclass(frozen=True)\nclass SearchResult:\n    """Une correspondance : bloc concerné, où dans le bloc, et un extrait."""\n\n    block_id: str\n    block_type: str\n    location: str\n    snippet: str\n\n\ndef _make_snippet(text: str, query: str) -> str:\n    """Extrait `text` autour de la première occurrence de `query`."""\n    lowered = text.lower()\n    index = lowered.find(query.lower())\n    if index == -1:\n        return text[: _SNIPPET_RADIUS * 2]\n    start = max(0, index - _SNIPPET_RADIUS)\n    end = min(len(text), index + len(query) + _SNIPPET_RADIUS)\n    prefix = "…" if start > 0 else ""\n    suffix = "…" if end < len(text) else ""\n    return f"{prefix}{text[start:end]}{suffix}"\n\n\ndef search_document(document: Document, query: str) -> list[SearchResult]:\n    """Recherche insensible à la casse dans tout le document."""\n    query = (query or "").strip()\n    if not query:\n        return []\n    lowered_query = query.lower()\n    results: list[SearchResult] = []\n\n    for block in document.blocks:\n        if isinstance(block, (TextBlock, HeadingBlock, QuoteBlock, CodeBlock)):\n            content = getattr(block, "content", "")\n            if lowered_query in content.lower():\n                results.append(\n                    SearchResult(block.id, block.type, "Texte", _make_snippet(content, query))\n                )\n\n        elif isinstance(block, ChecklistBlock):\n            for item in block.items:\n                text = item.get("text", "")\n                if lowered_query in text.lower():\n                    results.append(\n                        SearchResult(\n                            block.id,\n                            block.type,\n                            "Checklist — élément",\n                            _make_snippet(text, query),\n                        )\n                    )\n\n        elif isinstance(block, ListBlock):\n            for item in block.items:\n                text = item.get("text", "")\n                if lowered_query in text.lower():\n                    results.append(\n                        SearchResult(\n                            block.id, block.type, "Liste — élément", _make_snippet(text, query)\n                        )\n                    )\n\n        elif isinstance(block, TableBlock):\n            for row in block.rows:\n                for column in block.columns:\n                    value = str(block.get_cell(row["id"], column["id"]) or "")\n                    if lowered_query in value.lower():\n                        column_name = column.get("name") or "sans nom"\n                        results.append(\n                            SearchResult(\n                                block.id,\n                                block.type,\n                                f"Tableau — colonne « {column_name} »",\n                                _make_snippet(value, query),\n                            )\n                        )\n\n        elif isinstance(block, SimpleTableBlock):\n            for row_index, row in enumerate(block.rows):\n                for cell in row:\n                    if lowered_query in cell.lower():\n                        results.append(\n                            SearchResult(\n                                block.id,\n                                block.type,\n                                f"Tableau simple — ligne {row_index + 1}",\n                                _make_snippet(cell, query),\n                            )\n                        )\n\n    return results\n'
_SOURCES['core.version'] = '"""\nVersion de l\'application (PATCH 42 — Version 1.0).\n\nSource unique de la version, pour éviter qu\'elle diverge entre le\ntitre de la fenêtre, la fenêtre "À propos" et la documentation.\n"""\n__version__ = "1.0.0"\n'
